window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_070"]={"n":"孙蕡","dyn":"明","poems":[{"t":"代友赠别","f":"五言古诗","c":["金兰结深契，厚爱兄弟亲。","欢娱暂相违，一日胜九春。","如何舍我去，去逐衢路尘。","行役冒雪霰，驱驰极宵晨。","寒雀思集树，冻池念潜鳞。","物微尚有托，君作岁晚人。","岁晚风已寒，萧萧吹车轮。","征袍弊不补，野饭新亦陈。","别曲乱无腔，别酒醉失巡。","私情岂遽忍，欲止知何因。","落日如铜钲，远山生紫云。","君去意恻恻，我留涕纷纷。","王度今清夷，世途无荆榛。","前期慎努力，莫用怀苦辛。"]},{"t":"寄王给事佐","f":"五言古诗","c":["休沐展幽眺，步出钟阜阿。","卉木春气盎，淮水扬素波。","泛泛波上鸥，游泳鲜羽仪。","端坐愧此鸟，长游成蹉跎。","安得理归楫，翩然解佩珂。","扬舲过关右，鼓枻入江沱。","友于事宴集，物候方阳和。","酌酒南园上，与君同笑歌。"]},{"t":"输役萧墙","f":"五言古诗","c":["系组赴乌台，解佩辞禁垣。","弛刑许输役，获谴尚承恩。","局蹐感明宥，引咎复何言。","平明操板筑，日没就徽缠。","寒气袭敝裘，重负赪我肩。","抚己谅无愧，服勤思盖愆。","息杵入屏城，仰瞻东华门。","祥风拂左纛，卿云护彤轩。","翚凤丽羽翰，飞棱高中天。","重关起象魏，光彩一何鲜。","百辟罗周行，鸣珂翕锵然。","皋夔俨穆肃，董贾来翩翩。","白日光昭融，下照宁有偏。","微命嗟薄劣，独兹阻周旋。"]},{"t":"寄琪琳黄道士","f":"五言律诗","c":["雨绝天景佳，前荣树光绿。","遥怜采芝侣，远在春山曲。","琴歌久已断，酒赋何由续。","有约今夕同，开樽扫茅屋。"]},{"t":"南园歌赠王给事彦举","f":"古风","c":["昔在越江曲，南园抗风轩。","群英结诗社，尽是琪琳仙。","南园二月千花明，当门绿柳啼春莺。","群英组络照江水，与余共结沧洲盟。","沧洲之盟谁最雄，王郎独有谪仙风。","狂歌放浪玉壶缺，剧饮淋漓宫锦红。","青山日落情未已，王郎拂袖花前起。","欢呼小玉弹鸣筝，醉倚庭梧按宫徵。","哀弦泠泠乐未终，忽有华月出天东。","裁诗复作夜游曲，银烛飞光白似虹。","当时意气凌寰宇，湖海诗声万人许。","酒徒散落黄金空，独卧茅檐夜深雨。","分飞几载远离群，归来城市还相亲。","闲来重访旧游处，苍烟万顷波粼粼。","波粼粼，日将夕。","西风一叶凌虚舟，犹可题诗寄青壁。"]},{"t":"罗浮歌寄洛阳李长史仲修","f":"古风","c":["亭亭西樵峰，宛在南海湄。","日华丽仙掌，影漾金银池。","我昔扁舟恣长往，凌风浩荡烟霞想。","寻幽更欲探神奇，复向罗浮事仙赏。","仙家三十六洞天，罗浮夐与沧洲连。","丹霞射影四山静，群真环佩来翩翩。","蕊珠之峰数千丈，君时与我缘萝上。","水帘直下飞晴虹，万壑天风度流响。","山中刘郎司玉台，仙书授我琅函开。","心如明月炯虚照，身与浮云同去来。","此时会合那能再，尘土分飞忽三载。","我行奏赋登金门，君亦乘轺渡淮海。","淮海迢迢烟树深，相思岁晚结愁心。","长风万里碧云远，何由一寄还山吟。","山中洞房春寂寂，山中之人长叹息。","松花酒熟人不归，瑶草春风几回碧。"]},{"t":"白纻四时词四首 其一","f":"七言古诗","c":["姑苏台上春风和，江花乱落江水波。","交疏杨柳绿参差，华筵夜列开绮罗。","当筵西施间群娥，朱颜为君起微酡。","自拈红牙节清歌，飞花著人思繁多。","华月耿耿度斜河，疏星出河夜欲过，乌啼哑哑奈尔何。"]},{"t":"白纻四时词四首 其二","f":"七言古诗","c":["阊门辇路薰风时，江光潋滟芙蓉披。","翠羽霓旌照洲渚，銮舆出游初避暑。","西施含颦娇不语，群娥斗起歌白纻，回风舞袖为君举。","歌声窈窕一何长，白纻之白白如霜。","木瓜花红荔子香，东江月出西江光。","银壶酒多乐未央。"]},{"t":"白纻四时词四首 其三","f":"七言古诗","c":["馆娃宫畔风萧萧，芙蓉陨香杨柳凋。","银河影淡乌鹊桥，荧荧双星丽碧霄。","美人微醉脸红潮，筵前举袖催玉箫。","举歌白纻斗娇娆，越罗楚练风飘飘。","此时奉君情欲绝，铜龙夜深宫水咽，银床低转梧桐月。"]},{"t":"白纻四时词四首 其四","f":"七言古诗","c":["北风吹江日宛宛，江天飞雪帘栊满。","美人台上斗腰肢，羽觞流霞照华琯。","筵前西施含醉眼，歌停绿水声欲缓。","群娥玉环低款款，别宿台前水仙馆。","芙蓉帐高锦云暖，侬觉寒宵作那短。"]},{"t":"南京行","f":"七言古诗","c":["南京自古说豪雄，远胜秦中与洛中。","吴越千山高拱北，巴江一道远朝东。","秦淮水入丹阳郭，北固城连六代宫。","岌嶪石头如踞虎，逶迤钟岳似盘龙。","龙楼凤阁天中起，万户千门霄汉里。","太乙勾陈紫极通，翔鸾舞鹤珠峰峙。","却日觚棱驾寥廓，行空复道侵箕尾。","仙掌铜盘玉作流，灵芝华盖霞为绮。","华盖灵芝粲绮霞，御桥金水正当衙。","五门彩旭朝天仗，驰道香风散日华。","细柳千章争拂地，娇莺百啭竞啼花。","紫电龙光飞武库，雕甍甲第列侯家。","侯家卿相真才彦，玉笋蝉联奉天殿。","屈宋摛文入石渠，韩黥耀武专方面。","黄阁承恩宣雨露，乌台执法行霜霰。","环佩声清散早朝，葡萄酒绿沾春宴。","春宴春风坐百花，归来里巷斗香车。","金张富贵人争羡，王谢风流世共誇。","隐约商笳随赤羽，葳蕤大纛映彤牙。","盘陀宝校光前导，组络鸣镳隘狭斜。","狭斜西下通三市，紫雾红尘拂天起。","南陌东厢马似龙，乌衣朱雀人如蚁。","争看买珠轻薄儿，亦讶探丸游侠子。","犹怀凤台醉李白，无复新亭泣周顗。","井傍美人悲丽华，道上行人谭结绮。","结绮临春总可怜，龙河一带但寒烟。","天界丛林开象魏，冶亭高阁艳神仙。","神仙尽是蓬瀛侣，更画秦台玉箫女。","渺渺青鸾月下来，飘飘彩凤云中举。","别有青楼大道旁，烟花万树俨成行。","飞琼袅袅翠罗袖，小玉峨峨红粉妆。","小玉飞琼两少年，清歌妙舞斗嫣妍。","舞态盘回芳树底，歌喉宛转落花前。","彩云作雨朝朝合，璧月流光夜夜圆。","朝朝暮暮长如此，秋月春花若流水。","去岁今年景不殊，南来北去人相似。","生绿罗屏遮上客，流苏帐暖邀公子。","烂漫三春锦绣城，空濛一片笙歌市。","繁华佳丽乐无边，我独胡为困一廛。","已似扬雄栖白屋，还如司马卧文园。","谁将积业三千牍，换取扬州十万缠。","桃李风前歌扇底，看花骑马过年年。"]},{"t":"将进酒","f":"七言律诗","c":["青瑶案上离鸾琴，一徽已直千黄金。","开樽花下对明月，欲弹一曲还沉吟。","沉吟沉吟几低首，且弹商声劝君酒。","雍门风树春萧萧，地下田文骨应朽。"]},{"t":"蒋陵儿","f":"七言古诗","c":["蒋陵健儿身手捷，青年好游仍好侠。","锦衣绣帽彩丝囊，绿鬓葱茏映朱颊。","春风二月蒋陵西，柳暗秦淮花满堤。","窈袅金鞍摇日出，轻盈紫陌踏花嘶。","佳人纨扇和诗赠，上客金瓶带酒携。","上客留连正及时，佳人妙舞斗腰肢。","舞回璧月当空见，歌罢杨花似雪飞。","杨花似雪纷纷落，酣醉人前誇浪谑。","自然不分揖金张，况肯低头拜卫霍。","意气由来凌七贵，豪华岂必资三略。","五侯宅里听啼莺，廷尉门前弹罗雀。","扬雄寂寞掩柴扉，草得《玄》成鬓若丝。","岁岁年年书阁底，惟应羡杀蒋陵儿。"]},{"t":"梁父吟","f":"古风","c":["江水何深深，青枫映云林。","衡门一杯酒，抱膝《梁父吟》。","君不见夷吾奋袂投南冠，故人荐引登君门。","扬眉吐论下荆楚，纠合冠裳朝至尊。","又不见乐生徒步从西来，燕平一拥帚，调笑黄金台。","辕门一日见旌节，七十齐城生暮埃。","古来英俊人，所遇皆有立。","袖拂骊龙珠，能令鬼神泣。","而我独何为，幽泉冻蛟蛰。","荒萝绕屋秋雨凉，山鬼吹灯冷光湿。","几欲乘风朝太清，芙蓉缥缈白玉京。","天田角井散烟雾，阿香布鼓琅珰鸣。","星辰可望不可即，手把琅玕空复情。","为臣自古良独难，我更怀之摧肺肝。","田彊古冶三猛士，昔者虎视青齐间。","误罹相国二桃计，恨血今为春草斑。","白头勋旧且如此，何况新知而腼颜。","《梁父吟》，声正苦。","日落未落天星黄，西园灌木秋楚楚。","青青千里草如雾，兀兀当涂高踞虎。","长陵百尺空嵯峨，夜半山精泣风雨。","世无女娲五色石，天柱欲倩谁人补。","荆州水碧岷峨青，思美王孙渺何许。","《梁父吟》，声苦伤。","歌阑玉壶缺，白发千丈长。","起坐击长剑，仰天悲流光。","西归白日为谁晚，东流之水何泱泱。","青冥黄鹄傥垂翅，我亦凌风随尔翔。"]},{"t":"短歌行","f":"古风","c":["击长剑，和短歌。","短歌声无欢，调促情苦多。","盼流光，疾逝波。","青铜霜飞奈老何。"]},{"t":"牧羊词","f":"古风","c":["陇羊尾筛筛，山虎毛离离。","愿得山虎死，陇羊长自肥。","苍茫大化良亦苦，怪底生羊复生虎。"]},{"t":"蚕妇词","f":"古风","c":["朝看箔上蚕，暮取茧上丝。","丝成给日食，不得身上衣。","早知阿家蚕事苦，不若当初学歌舞。"]},{"t":"闺中闻子规","f":"七言律诗","c":["交疏日射房栊晓，碧树初闻子规鸟。","惊回残梦了无欢，惨切春愁破清悄。","独宿何曾下绣帏，宁劳劝我不如归。","莺花烂熳江南道，好向游人醉处啼。"]},{"t":"骊山老妓行补唐天宝遗事戏效白乐天作","f":"七言古诗","c":["秋风杨柳凋金缕，冷露芙蓉落芳渚。","寒香晚色何所如，骊山唐姬教坊女。","蛾眉淡扫山远碧，蝉鬓半抛云乱吐。","时妆无复新妖娆，曩态犹存旧娇妩。","我昨咸阳纵冶游，冶游烂熳遍西州。","青山直抵双龙阙，绿水横过五凤楼。","南国佳人金错落，长安公子玉骅骝。","银壶送酒青丝络，皓齿当筵白雪讴。","琵琶横笛空聒耳，唐姬搊筝妙无比。","请弹一曲久含羞，呼唤百回方强起。","移柱相参雁成列，调弦未就人先喜。","俯首斜拖珠步摇，向人高露春纤指。","楼高韵发响泠泠，急管悲歌一霎停。","初听乍如风雨至，再弹还作凤凰鸣。","清如玉女钧天奏，壮似雕戈出塞声。","涧水带冰时哽咽，春雷震石忽凭陵。","凭陵未已旋清悄，清悄渐凝声渐小。","四座无言俱寂寥，馀音已断犹萦绕。","溶溶宛宛复悠悠，切切凄凄还窈窈。","深闺断蚓怨寒宵，浅谷娇莺破春晓。","缠绵万恨与千愁，婉意柔情不肯休。","蔡琰胡笳悲紫塞，班姬团扇掩清秋。","楼前皓月明如练，天外行云凝不流。","促拍未终南内曲，新腔忽过《小梁州》。","梁州一摺月向午，唐姬此时心独苦。","银甲悲深不忍弹，衷肠断尽无由语。","低笼翠袖揾香泪，翻使欢娱变悽楚。","诉尽平生富与贫，可怜人世今成古。","忆昔开元正太平，儿家生长在天京。","十三学舞曾惊座，十四搊筝能擅名。","玉貌羞花长窈窕，宫腰怯柳更轻盈。","春寒不离鸳鸯枕，日晏方开孔雀屏。","五陵年少秦川客，争爱儿家好颜色。","殢雨尤云最恼人，追欢买笑宁论直。","声名每出流辈上，风致独觉旁人惜。","承恩况得登掖庭，宛转随龙侍君侧。","海晏河清久息兵，四夷宾贡尽充庭。","炎方已见来丹荔，交趾还闻进雪鹦。","耀日香车连紫陌，飞云画栋列朱甍。","空濛一片笙歌海，浩荡三春锦绣城。","骊山山上多楼阁，万户千门通碧落。","大驾深居在九重，四时多暇惟行乐。","已营连昌胜结绮，复起芳凤齐花萼。","壶飞玉女递更筹，舟戏金龙动鳞角。","侍臣传敕选娇容，特许儿家步辇从。","宫扇影移花雨外，山呼声沸锦云中。","千株火树争明月，万炬金莲斗彩虹。","《子夜》歌词翻《白雪》，《霓裳》舞队散旋风。","歌停舞歇徘徊久，银筝独进纤纤手。","明眸丽质一当前，含颦美人俱在后。","数声清响动弦索，八面凉风生户牖。","艳曲新裁萼绿华，中官催赐葡萄酒。","年年秋月复春花，多在宫中少在家。","娇笑不愁宫监怒，艳妆长得阿姨誇。","朝游复道瞻天表，夜步西厢拜月牙。","斗草经春陪虢国，藏阄竟夕伴昭华。","韶光忽逐流年转，野鹿衔花上林苑。","铁骑东来凤阙空，金根西狩蛾眉远。","上方无复听宣召，新籍宁辞避差遣。","约臂金环雨雪宽，凌波锦袜风埃蹇。","星移物换得无情，复向骊山悄地行。","紫禁无人芳草合，瑶阶雨过绿苔生。","歌台索寞花千树，舞榭苍凉月半棂。","绣阁秋阴连琐闼，铜仙清泪落金茎。","高梧陨翠莲飘玉，太乙勾陈看不足。","百子楼寒雾影昏，长生殿古烟光绿。","宫墙瓦落见蒿莱，辇路尘生走麋鹿。","舞马雕床恼梦思，花奴羯鼓惊心目。","故宅新人作宴游，内家红锦列缠头。","珠帘绣柱俄成梦，凤管龙笙总是愁。","旧曲闻来眉自敛，盛年说着口应羞。","飞蓬短鬓难禁白，老屋疏茅不柰秋。","舞衫长借邻人着，同伴相呼只推却。","脸玉香随翠靥消，泪珠暗逐灯花落。","忧来倒插黄金凤，梦里时弹《白翎雀》。","百感中来不自由，芳心一片从谁托。","唐姬言语一何长，句句凄其字字伤。","满座闻之声唧唧，沾巾我亦为浪浪。","沧桑转瞬谁能识，富贵浮云安可常。","览镜每闻悲素发，举杯长欲劝流光。","唐姬亦莫怀抱恶，自古佳人多命薄。","倾城西子逐鸱夷，绝代明妃嫁沙漠。","尊前有酒且欢笑，身外閒愁付冥漠。","皎月秋来几度圆，秾花春尽从渠落。","唐姬揽涕复陈情，请作《骊山老妓行》。","桃李风前霜月下，长吟亦足慰平生。","不因水上琵琶语，那识江州司马名。","为尔临风歌一曲，百年哀怨起秦筝。"]},{"t":"高昌老翁行","f":"七言古诗","c":["高昌老翁背隆然，黄须高鼻毛发拳。","自言少小家幽燕，生长适值繁华年。","出身从戎事西边，十七八九南营田。","雕戈如云护中坚，流苏帐暖垂蜿蜒。","三珠虎符谁喜悬，偏裨尽戴黄金蝉。","军中无事惟游畋，锦袍白马青连钱。","胡鹰一掣冲九天，鴐鹅洒血来连连。","夜阑爱月醉不眠，众宾呼卢各争先。","输筹唱饮开锦筵，美人照座红娟娟。","凉州葡萄斗十千，金盘丹荔明珠圆。","野驼之酥香不膻，争持宝刀誇割鲜。","忽尔不乐心悁悁，琵琶催张凤凰弦。","纤歌一曲清声传，华严天魔间采莲。","美人起舞斗嫣妍，腰肢宛转飞花旋。","玉钗斜横翠袖偏，春风徐来拂筵前。","此时意气如熊虎，伯仲联翩享圭组。","青云头上高楚楚，却笑旁人不好武。","一朝零落来南土，白发萧萧守环堵。","北风怒号朔雪舞，羊裘无温敝不补。","人间俯仰成今古，老翁无乃独愁苦。","霸陵将军旧征虏，青门秦侯亦开府，浮荣飘风何足数。"]},{"t":"湖州乐","f":"七言古诗","c":["湖州溪水穿城郭，傍水人家起楼阁。","春风垂柳绿轩窗，细雨飞花湿帘幕。","四月五月南风来，当门处处芰荷开。","吴姬画舫小于斛，荡桨出城沿月回。","菰蒲浪深迷白纻，有时隔花闻笑语。","鲤鱼风起燕飞斜，菱歌声入鸳鸯渚。"]},{"t":"云南乐","f":"七言古诗","c":["成都贾客向人语，黎州多风杂多雨。","雪山万古长不消，山下四时风气暑。","竹林西畔是云南，不论冬夏披毡衫。","蛮官见客花布袄，村妇背盐青竹篮。","绳桥跨涧石巀嶪，部落马蹄皆灌铁。","引筒贯索通客行，插木入崖防栈绝。","郫筒酒熟蛮人歌，太平今喜无兵戈。","悬车不戍相公岭，卖马安行大渡河。","牛缨换贷跻邛笮，路出彭门缘剑阁。","火井秋篁截洞箫，几腔吹作云南乐。"]},{"t":"送高文质游杭州","f":"七言古诗","c":["君昔从戎佐南伯，归朝名在骁骑籍。","有儿戳枪能跨马，请官得应长番役。","繁华三月帝皇州，驰道千花过枣骝。","豪侠应怜白日晚，狭斜还作少年游。","玉瓶一双和酒络，九陌三衢纵欢谑。","白雪猧儿翠毯鲜，石榴裙子春纱薄。","今晨告我武林行，一束图书画舸轻。","宾客追随白下里，莺花明媚石头城。","苏堤雨馀春水长，三高祠下闻渔榜。","冷泉濯足乘风归，野寺哀猿共僧往。","可怜云水空西湖，画船迩来一只无。","沉酣久矣厌流俗，清冷正可娱潜夫。","武林旧日豪华国，一一烦君吊遗迹。","明朝白马拥波涛，前代铜驼卧荆棘。","铜驼翁仲事应非，惟有孤山似去时。","君行若过逋仙墓，折取梅花一两枝。"]},{"t":"白云山","f":"七言古诗","c":["白云山下春光早，少年冶游风景好。","载酒秦佗避暑宫，踏青刘鋹呼鸾道。","木棉花落鹧鸪啼，朝汉台前日未西。","歌罢美人簪茉莉，饮阑稚子唱铜鞮。","繁华往似东流水，昔时少年今老矣。","荔子杨梅几度红，柴门寂寂秋风里。"]},{"t":"赠皇甫隐士文远","f":"古风","c":["群英济济登庙堂，无复幽人卧空谷。","胡为冠带隐廛市，有似山海遗珠玉。","先生风度与人殊，面如赪玉仍秃须。","侯门不挂一步脚，厌杀人间呫嗫儒。","蒋陵白下清溪曲，垂柳疏疏数椽屋。","芸窗磊落一万卷，客去自倚风轩读。","秦淮买竹起高楼，兴来酌酒楼上头。","科头举白乱浮客，胡琴羌笛声啾啾。","朋宾自饮还自散，先生醉眠忘早晏。","蒲葵巨扇醉不醒，人定钟阑始知饭。","沉酣本以陶性灵，有时兀坐还惺惺。","屯蒙火足金母啸，卦气白白升黄庭。","看君出处有妙策，为人不迁亦不激。","随时无怪互隐显，意欲不遣人人识。","我作初交沈逸民，卜居遂与先生邻。","雪中长趿东郭履，花下时挂渊明巾。","生平落落人少喜，先生一见便知己。","非因性情酷相似，安得倾倒能如此。","居安食饱即为家，山林未必强京华。","君不见西湖处士骨已朽，至今惟有寒梅花。"]},{"t":"赠关元帅景熙","f":"七言古诗","c":["君在前朝帅东阃，虎符三珠秩二品。","辕门裨将悬金章，黄头奴子州县尹。","杨仆楼船下濑时，君随左相入京师。","端门万钱宴珠履，辇路千花明锦衣。","天官宗伯司邦典，藻鉴论君第高选。","君言下国羁旅臣，生来好武文笔浅。","愿绾铜章佐北征，还来作吏锦官城。","宣劳岂言爵高下，贵在晚节完虚名。","岁华荏苒容鬓改，朋旧飘零满湖海。","星辰霜木馀几人，我与蟾溪老高在。","前年佐县淮山阴，今春待诏入词林。","比来奉节领祀事，会面错愕惊愁心。","郫筒新酒凝寒翠，清夜悬灯共君醉。","醉来自起弹鸣筝，一曲清歌数行泪。","有歌有酒君莫辞，人生会遇信有时。","百年莽莽任所适，不必借箸筹前期。","但怜奔波稀会面，此去何时复相见。","明朝挂席下瞿塘，我似伯劳君似燕。"]},{"t":"戏赠端孝思","f":"古风","c":["君不见长安游侠儿，银鞍白马青春时。","朝出呼卢夜饮酒，美人娟娟照窗牖。","若为君作梅花仙，不随桃李争春妍，临流自敞书画轩。","独夜可怜邀月饮，一春长是背花眠。"]},{"t":"送何都阃济南省亲至京还广","f":"七言古诗","c":["伊昔关河事征战，君家严君拥方面。","君拜元戎领大藩，虎旗耀日光于电。","北山之北南河南，鲸波虎垒相巉岩。","辕门上日开将阃，白马朱缨银作衔。","军中呼卢日向午，锦筵置酒夜击鼓。","龙潭降卒解西歌，翁源女儿学东语。","有时俘贼珠海头，海门六月如九秋。","牙旗挥天虎豹怒，霹雳迸火鱼龙愁。","银汉淋漓洗穹昊，严亲入觐承恩早。","角巾还第谁最高，君与君家兄弟好。","朅来宁亲东入齐，归舟一系蒋陵西。","莺花烂熳春如海，歌舞流连醉似泥。","蟾溪高彬故部曲，开宴斗门桥下屋。","宣州梨子鹅儿黄，吴姬指纤白如玉。","酒酣耳热悲故乡，孙蕡在座情更伤。","关河北去五千里，目断南天如许长。","秦淮水生风似雨，十幅蒲帆醉中举。","龙湾江口辞故人，小孤洲北失前侣。","知君第宅绕西湖，门对罗浮列画图。","梅花白白想犹昨，芦橘青青今有无。","三郎今年三十几，平生与蕡最知己。","明岁春还若寄书，玉堂华馆西清里。"]},{"t":"往平原别高彬","f":"七言古诗","c":["银壶绿酒沾春宴，环佩朝回奉天殿。","平生不作儿女悲，独向高彬泪如霰。","高彬昔年桑梓雄，好贤乃有古人风。","东林诗社静来结，北海酒樽长不空。","朅来弓剑已萧索，短发如丝犹好客。","塞上葡萄火齐红，宣州梨子鹅儿白。","沉绵不独重相知，文采今还胜昔时。","小楼焚香每读《易》，净几把笔常题诗。","今晨我作平原别，高彬不意情欲绝。","芙蓉香冷不堪赠，杨柳枝黄未宜折。","龙湾江口石城头，一幅蒲帆万里秋。","暮云红树傥相忆，应有音书慰别愁。"]},{"t":"寄诃林长老明静照","f":"七言古诗","c":["庞眉老僧无住着，不问山林与城郭。","谈禅到处即跏趺，白昼天花如雨落。","心知一境万缘空，静与晴霄海月同。","锡振春山常伏虎，钵含秋水自藏龙。","问师今年僧腊几，手种苍松旧松子。","松身已作蛟龙鳞，定中一念犹未起。","白石垂萝净窈冥，炉香一炷两函经。","涧猿时擎野果供，山鬼或倚寒岩听。","荷为袈裟荔为带，世人见者皆再拜。","师言是悉有漏因，我今已入无色界。","十年奔走乱如丝，对榻空论不遂期。","每叹道缘于世浅，惟师与我最相知。"]},{"t":"赠虹县颜景明","f":"七言古诗","c":["淮阳老人读《周易》，风吹鬓丝人不识。","兴阑移席傍寒梅，双眼如猫对花碧。","天风毛骨江海仙，偶来花下同清缘。","凌云文采凤凰见，照室丹光龙虎全。","清琴调古无人续，且可开樽扫茅屋。","胎禽起舞和云谣，山月光于画楼烛。"]},{"t":"次武昌","f":"七言古诗","c":["大风吹船如马走，船头水声作牛吼。","挂帆初发岳阳矶，转柁俄湾武昌口。","武昌城头黄鹤楼，飞檐远映鹦鹉洲。","汉阳树白烟景湿，行人如鸥沙际立。","江南风土寒气迟，居人九月着絺衣。","酒旗临江开竹屋，当垆小姬能楚曲。","蜻蜓船尾旋回风，今夕停船酒家宿。"]},{"t":"题钱叔昂潇湘图","f":"古风","c":["远山如游龙，近石如踞虎。","秋阴迢迢树楚楚，乃是洞庭潇湘之极浦。","西来白波浮太虚，鬼物似与空濛俱。","潭深蜃气结楼阁，鲛人踏浪随游鱼。","织绡更泣明月珠，缀成悬珰素裙襦。","九疑并迎翠华辇，绛节影低群真趋。","须臾长风起木末，高林侧亚叶乱脱。","浮云散尽天宇豁，云水遥连带青阔。","苍松翠竹黯未分，残霞断霭馀斜抹。","钱郎毛骨清，画此兼众妙。","疏疏临水花，白白远山晓。","恍疑一叶寒流中，雨后开篷展清眺。","日落君山吹凤箫，水云相间作箫《韶》。","荒祠二女应魂断，试把芙蓉天外招。"]},{"t":"次归州","f":"七言古诗","c":["归州城门半天里，白云晚向城下起。","市廛架屋依岩峦，妇女提罂汲江水。","巴山雪消江水长，城中夜闻滩濑响。","客船树杪钩石棱，渔父云端晒缯网。","家家芜田山下犁，倒枯大树烧作泥。","居人养犬获山鹿，稚子缚柴圈野鸡。","楚王台高对赤甲，四时猛风长飒飒。","柁工鸣板避漩涡，橹声摇上黄牛峡。"]},{"t":"发忠州","f":"七言古诗","c":["颠风翻山云黑黑，星河无光江翕翕。","摇船夜半发忠州，漩深浪紧船欲立。","宣公祠下滩嘈嘈，船头着水低复高。","石棱割裂箕斗影，山鬼出杂鱼龙号。","亦知风水莽回互，王事有程那得顾。","谁歌太白《蜀道难》，和我灵均《远游》赋。"]},{"t":"下瞿塘","f":"七言古诗","c":["我从前月来西州，锦官城下十日留。","回船正值九九节，巫山巫峡风飕飕。","人言滟滪大于马，瞿塘此时不可下。","公家王事有程期，敢惮微躯作人鲊。","人鲊瓮头翻白波，怒流触石为漩涡。","柁公敲板助船客，破浪一撇如飞梭。","滩声橹声历乱聒，紧摇手滑橹易脱。","沿洄划转如旋风，半侧船头水花没。","船头半没船尾高，水花作雨飞鬓毛。","争牵百丈上崖谷，舟子快捷如猿猱。","拢船把酒聊自劳，因笑轻生博奇好。","吟诗未解追谪仙，天遣经行蜀中道。","巴东东下想安流，便指归州向峡州。","船到岳阳应渐稳，洞庭霜降水如油。"]},{"t":"游罗浮三首 其二","f":"七言律诗","c":["四百峰峦列海图，飞云绝顶敞玄都。","丹砂五色时光焰，紫翠中天半有无。","观里松株皆住鹤，山中竹叶尽成符。","铁桥归去寻清赏，烂醉仙人白玉壶。"]},{"t":"江上","f":"七言律诗","c":["江上青枫初着花，客帆和月宿蒹葭。","透云疏雨数千点，临水小村三四家。","风起渔船依钓石，潮回归雁认平沙。","秋怀已向南天尽，又是沧洲阅岁华。"]},{"t":"古意","f":"七言绝句","c":["山矾花落春风起，吹妾芳情渡江水。","梦中蝴蝶相交飞，门外鹊声郎马归。"]},{"t":"送翰林宋先生致仕归金华二十五首 其四","f":"七言绝句","c":["门生日日侍谈经，独向孙蕡眼尚青。","几度背人焚谏草，风灰蝴蝶满中庭。"]},{"t":"送翰林宋先生致仕归金华二十五首 其五","f":"七言绝句","c":["千载班扬亚六经，先生高步续芳声。","高丽日本朝王使，长向仙班问姓名。"]},{"t":"送翰林宋先生致仕归金华二十五首 其七","f":"七言绝句","c":["头白勋庸列上卿，君王岂是重文名。","朝廷礼乐新寰宇，半是先生撰次成。"]},{"t":"送翰林宋先生致仕归金华二十五首 其十","f":"七言绝句","c":["事业文章满汗青，白头归去世缘轻。","双溪水绕苍松下，唯读楞伽一卷经。"]},{"t":"送翰林宋先生致仕归金华二十五首 其十一","f":"七言绝句","c":["红鞋金带荔枝花，三品词林内相家。","归去山中无个事，瓦瓶春水自煎茶。"]},{"t":"送翰林宋先生致仕归金华二十五首 其十四","f":"七言绝句","c":["玉树芝兰取次成，小孙开岁亦能行。","悬灯夜读元朝史，认得前编老祖名。"]},{"t":"送翰林宋先生致仕归金华二十五首 其十八","f":"七言绝句","c":["近欲长参不语禅，水云飞尽月轮圆。","惟馀一册龙门子，留与西江学者传。"]},{"t":"送翰林宋先生致仕归金华二十五首 其二十","f":"七言绝句","c":["华发朱颜六秩馀，还乡犹驾软轮车。","龙江关吏如相识，应止青牛乞著书。"]},{"t":"寄高彬","f":"七言绝句","c":["条风吹绿满蟾溪，蜡屐行春日向西。","独木桥边乌桕树，鹁鸠飞上上头啼。"]},{"t":"寄王彦举","f":"七言绝句","c":["绿杨阴下玉骢嘶，丝络银瓶带酒携。","梦入南园听夜雨，不知身在蒋陵西。"]},{"t":"过扬州二首 其一","f":"七言绝句","c":["江上垂杨覆白蘋，斜阳啼鸟断吟魂。","朱楼翠箔金何在，一带寒城锁暮云。"]},{"t":"过扬州二首 其二","f":"七言绝句","c":["垂杨白白折残枝，春尽琼花作雪飞。","少日狂游今是梦，竹西歌吹旧台池。"]},{"t":"秋闺思四首 其二","f":"七言绝句","c":["凉夜箫声处处过，玉楼高起逼天河。","西风瘦尽梧桐叶，添得西窗月影多。"]},{"t":"闺怨一百二十首 其十五","f":"七言绝句","c":["晚思沉沉倦倚阑，玉箫声歇酒阑珊。","澹云还掩初生月，谁护梨花作夜寒。"]},{"t":"闺怨一百二十首 其三十","f":"七言绝句","c":["夜漏沉沉似岁长，小鬟贪睡懒添香。","春风莫撼流苏帐，待妾分明梦一场。"]},{"t":"访某驸马不遇题壁","f":"七言绝句","c":["青春驸马不还家，公主传宣坐赐茶。","十二碧栏春似海，隔窗闲杀碧桃花。"]},{"t":"阙门书所见","f":"七言绝句","c":["隐隐旌旗飐落晖，方山遥望锦城围。","平芜一带香尘合，知是诸王射猎归。"]},{"t":"赠鹤林周玄初尊师","f":"七言律诗","c":["物外逍遥月鼎翁，先生早岁得相从。","榴皮画壁成黄鹤，竹叶书符化绿龙。","天女时闻苍水佩，世人空拜累珠峰。","神游倘遂烟霞约，便解朝衣问赤松。"]},{"t":"周玄初祈晴诗","f":"七言古诗","c":["江南仙山天下无，峰峦屹立龙虎都。","赤城嵯峨敞灵区，中天秀色光盘纡。","紫极曲密交绮疏，郁萧弥罗玉渠渠。","宸严中高天帝居，璇题丹篆双蛟扶。","美人风鬟绣罗襦，华容绰约春花敷。","星为华盖霞为旟，列缺丰隆一字趋。","文昌司勋丹桂厨，廷尉执法森雕殳。","真人狞色虬髯须，华岳攒云冠翠岨。","雪山青城角井孤，碧桃吹香蜀锦如。","先生丰度常人殊，苍姬为姓字玄初。","携琴南来访华胥，神清骨冷惊座隅。","琅函石室启秘图，谷神天机守若愚。","经巢重营向姑苏，绿树荫屋江循除。","何年声名达銮舆，入陪夔龙达天衢。","天颜津津降都俞，御炉雾绕青霓裾。","东溟巨涨吞三吴，秋阳化霖没菑畲。","堂筵产蛙釜生鱼，平陆滉漭成江湖。","妖霾阴霏塞四墟，洪涛墨汁翻舳舻。","老农仓惶忧国租，百万伛指将沦铺。","先生被发骑于菟，俯为苍生出蓬壶。","手扶芙蓉绿湛卢，灵蛇穿星胆气粗。","蘸笔露叶书阴符，封章奏伏红氍毹。","天坛赤脚踏斗觚，叱喝百鬼如佣奴。","千山万山雨模糊，划然清空见杉槠。","阳侯擎盘献金乌，若木散彩干泥涂。","飞廉崩腾运飙车，海屋撼折青珊瑚。","冯夷首缩寒蟾蜍，天吴却走尾毕逋。","欢声如雷隘皞阇，鹑衣鹤发歌里闾。","我本逍遥山泽臞，不才分比栎与樗。","颜面偶出应时需，勃郁坐困尘土拘。","石床蕙帐松菊枯，铁桥流水空罗浮。","藜羹不充出无驴，况望宦达高名誉。","沧波东深芳景徂，惊禽不定林木疏。","羊肠九折方崎岖，我行欲进仍趑趄。","纷纶世事集眇躯，有若万弩向一狙。","逝言乞身承明庐，分我水竹出南嵎。","清泉白石邻樵渔，松花春酝倾浮蛆。","呼龙画江种金蕖，倩鹤渡海传丹书。","玄言五千味道腴，妙香萦帘日欲晡。","凝神坐忘隐团蒲，关元晃朗天为徒。","坎离匡郭太一炉，黄庭有士身衣朱。","白虎啸风作熬枢，苍虬摧鳞与之俱。","龙喑虎哑不须臾，虚室发白延居诸。","泥丸三花暖将舒，蜩蝉蜕壳鸡抱雏。","长吟洞章夜冲虚，左骖翔鸾右飞凫。","班行朝回步虚徐，琅风清微韵笙竽。","蚩尤卷旗枉矢袪，立召霹雳诛猰貐。","丹砂如粟仓箱储，一粒入口千年余。","颠崖赤子凋瘵苏，四海尽化为唐虞。","五星聚奎贯联珠，麒麟游郊凤栖梧。","崆峒影掠周八驹，龟台阆风宴仙姝。","归来松阴倚蜘蟵，酡颜谑笑解玉琚，与君岁晚同游娱。"]},{"t":"次张仲举诗韵四首 其一","f":"七言绝句","c":["重重叠叠水南峰，五五三三石上松。","钓艇荡归春雨足，草堂犹有白云封。"]},{"t":"杂诗六首 其一","f":"五言古诗","c":["飘风振长薄，夕日澹无辉。","良人久楚蜀，今在沅水西。","别时春花发，秋叶忽已飞。","无由通精神，梦寐长相随。","欲寄一尺书，临风久徘徊。","游鳞没水风，征雁杳云涯。","哀猿常对吟，冻乌亦并栖。","居然独处廓，坐使恩爱违。","何能一会晤，以慰凄恻怀。"]},{"t":"杂诗六首 其二","f":"五言古诗","c":["浮萍无根蒂，泛泛江海间。","狂风簸巨浪，漂泊何当还。","亦似离家客，长年去乡关。","莽莽涉万里，迢迢度千山。","沉忧损精魂，远道多苦颜。","无为歌此词，恻怆伤肺肝。"]},{"t":"杂诗六首 其三","f":"五言古诗","c":["大堤有游女，盛服佩鸣珰。","冶容丽皎日，锦绮华若英。","含情采秋绿，薄暮不盈筐。","问女何所思，叠叠哀怨长。","夫君久离索，杳邈江与湘。","寒凉人短褐，波浪泛舟航。","芙蓉谢初夕，岩桂亦已芳。","渺渺燕北归，飞飞雁南翔。","风飘流尘起，木落天雨霜。","俯视惭游鱼，仰观愧七襄。","此情君讵察，怀玉空自伤。"]},{"t":"杂诗六首 其四","f":"五言律诗","c":["灿灿园中树，灼灼枝上花。","朝迎云间日，暮逐东逝波。","秦楼起荒烟，郑谷栖馀霞。","浮云等雾露，富贵焉足多。"]},{"t":"杂诗六首 其五","f":"五言古诗","c":["边城亘长云，迢迢接沙漠。","时平宣威远，壮士从军乐。","霜风朝出猎，锦旆明挥霍。","营田悬两狼，都护挂双貉。","前茅拥宛骑，后劲吹羌角。","官勋四时转，征战胡尘邈。","腐儒身计疏，中夜思奋跃。","何能投章甫，从尔上麟阁。"]},{"t":"杂诗六首 其六","f":"五言律诗","c":["十月良家子，从征上边州。","明月照镜匣，北风吹马头。","少年有奇志，思欲分国忧。","谁能学李广，百战不封侯。"]},{"t":"南园","f":"五言古诗","c":["诗社良宴集，南园清夜游。","条风振络组，华月照鸣驺。","高轩敞茂树，飞甍落远洲。","移筵对白水，列烛散林鸠。","雅兴殊未央，旨酒咏思柔。","玉华星光灿，锦彩云气浮。","丽景不可虚，众宾起相酬。","长吟闲剧饮，楚舞杂齐讴。","陵阳杳仙驾，韩众非我俦。","聊为徇时序，娱乐忘百忧。"]},{"t":"南园夏日饮酬王赵二公子澄佐","f":"五言古诗","c":["郡城多暇日，公子专幽寻。","招携无俗士，欢宴尽华簪。","临水钓游鱼，凌风弋高禽。","南园当盛夏，灏气涤烦襟。","澍雨朝浥道，流云豁轻阴。","芙渠被曲渚，灌木秀穷林。","展席罗长筵，美酒对坐斟。","交交黄鸟哢，聒聒玄蜩吟。","岁时递迁斡，圣贤皆销沉。","于时不痛饮，负此芳赏心。"]},{"t":"溪山小隐","f":"五言律诗","c":["日出景更好，流青入窗户。","木落叶上霜，泉添夜来雨。","策驴过石桥，傍舟向沙渚。","遇此休正期，何须羡簪组。"]},{"t":"道上作","f":"五言古诗","c":["高林翳当道，莽莽秋向深。","回风乱落木，骄阳亦化霖。","我行泥涂中，凄厉入我襟。","白日晦平陆，玄云生夕阴。","归鸟静不飞，暝猿长哀吟。","感此时景迈，况将阳月临。","不怨行路难，所嗟岁骎寻。","悲鸣激楚奏，思苦调南音。","钟仪久已死，谁复知此心。"]},{"t":"期罗浮萧炼师不至","f":"五言律诗","c":["石室松桂秋，凉风涤残暑。","柴门敞空谷，旷夕怀仙侣。","吹笙久不至，鹤驭今何许。","朗月流清辉，山中几延伫。"]},{"t":"崖山有感","f":"五言古诗","c":["崖山峙海门，乃宋沉国所。","双龙如九渊，义士赴疆虏。","妻子驱先沦，焚香亦何补。","我来吊忠魂，但见浪花舞。","底用玺发光，凄其为怀古。"]},{"t":"安期升仙台","f":"五言古诗","c":["神仙莫可稽，欲吊踪多漫。","惟有安期生，遗台粤山畔。","想当避秦乱，南还事冶锻。","砂采芙蓉灵，火炀电光烂。","丹成遂轻举，跨鹤涉云汉。","尚留如凫舄，世上作奇玩。","飞腾今何之，翘首起吁叹。"]},{"t":"夏日过蒲涧寺后二岩观菖蒲","f":"五言古诗","c":["炎威郁难据，况值日方永。","挥箑偕同袍，远诣山中静。","消暑得清泉，流来自岩顶。","循涧见石蒲，瀰布水光映。","猬毛刺针芒，虎须簇锥颖。","婆娑浓靛敷，翠色香挺挺。","传是古尧韭，一览心已领。","采饵可明目，烁烁电光耿。","尤堪引寿龄，久视阅遐景。","遂蹑安期踪，云路恣驰骋。","旋归乘天风，浩笑尘梦醒。"]},{"t":"寄琪琳黄道士墨竹","f":"五言律诗","c":["漾漾太湖水，涓涓文玉丛。","龙光起夕雾，凤羽生秋风。","冰轮出寒悄，瘦影筛玲珑。","因之怀所思，邈在蓬莱宫。"]},{"t":"寄关大举隐士","f":"五言古诗","c":["秋阳化为霖，流潦涨平陆。","阴霾晦万象，岁暮时运速。","居者窘营为，行者困驰逐。","晨兴起慨叹，旅怀伤局促。","飙风振丛薄，泥涂没车轴。","庭树无全柯，原草变馀绿。","静念穷居士，杳然苍山麓。","短褐才掩胫，糗糒常不足。","从事屡失会，养高动违俗。","空椟隋侯珠，谁明卞氏玉。","贫贱少知己，隐沦愧亲族。","励节希世贤，君子善自勖。"]},{"t":"西郊秋日","f":"五言古诗","c":["斗柄揭西晨，杪秋天气肃。","零落沾野草，惊飙振林木。","西畴农务成，勤忙事刈□。","岁时乐丰稔，膏泽遍穜稑。","思昔游京洛，寒至未成服。","弊裘感季子，知贫仰鲍叔。","哀乐如流电，抚己心已足。","无烦抱龟策，更就詹尹卜。"]},{"t":"南园怀李仲修","f":"五言古诗","c":["幽独摅雅怀，逍遥步南园。","繁卉耀阳德，嘉木秀春暄。","时旸燠土膏，流澌涨远川。","荃兰杨朱英，山樊炫文轩。","垂杨列曲渚，鸣鸟何关关。","展席芳醑陈，开觞群物妍。","顾瞻失俦侣，高情寄所宣。","驰思望远人，乃在伊洛壖。","贤劳事会计，日昃不遑安。","聊复纵长吟，引领希令言。","何能此会合，宴乐舒我颜。"]},{"t":"赠从弟三首 其一","f":"五言律诗","c":["鸿鹄在陂泽，立志恒不群。","独鹤唳九皋，音响常远闻。","令器逢盛时，岂将久湮沦。","无为秉孤节，甘与巢许邻。"]},{"t":"赠从弟三首 其二","f":"五言律诗","c":["青阳播林麓，百卉生光妍。","如何空谷资，尚尔霜霰缠。","守节抱苦贞，岂不幽且寒。","由来松柏性，羞学桃李颜。"]},{"t":"赠从弟三首 其三","f":"五言律诗","c":["荆山有良玉，韫此璞石中。","玉人雕琢之，始能成圭琮。","良玉岂非宝，亦在雕琢功。","愿言保令誉，黾勉光五宗。"]},{"t":"赠留隐士中美","f":"五言古诗","c":["商飙落庭木，芳岁倏巳周。","感此流序易，恻恻但怀愁。","念我同志友，不得偕宴游。","一居玉堂置，一在炎海陬。","王道今清平，有才赞鸿猷。","谁令抱孤志，坐恋林与邱。"]},{"t":"北上","f":"五言古诗","c":["京华文物盛，东南紫气浮。","祥云间甲第，春阳蔼道周。","观国方振缨，弹冠始鸣驺。","皋夔预接武，多士为我俦。","如何舍此去，北上赋远游。","扬帆渡淮水，驱马入青州。","青州非故乡，郁郁久难留。","西望太行巅，南临清济流。","行行日以远，役役安得休。","微官宦况薄，旅邸芳岁遒。","严风被草木，密雪沾衣裘。","迢遥百越地，杳邈炎海陬。","那能计归日，苦道阻且修。"]},{"t":"别弟","f":"五言古诗","c":["离离原上草，岁晚霜霰滋。","与子为兄弟，生世逢乱离。","漂荡各分散，生死安得知。","乐土叹无食，南州叹无衣。","良时幸休明，天路开清夷。","翩翩两鸿鹄，振翼思奋飞。","一留故山树，一望云中涯。","东西各异势，顾影相徘徊。","远道去茫茫，会合未有期。","吞声念同气，泪落不敢挥。","他乡傥言归，庶慰遥相思。"]},{"t":"别邻","f":"五言古诗","c":["谚云骨肉远，不若邻里亲。","往来旦夕念，眷意一何勤。","愿言永相保，不谓远离分。","携壶与挈榼，送我衢路津。","含愁向往轴，酌酒当霜晨。","恋恋疏者厚，依依故情新。","去去归未期，留家犹食贫。","有无通假借，此道古所敦。","无为忘寄托，别语多苦辛。"]},{"t":"别友","f":"五言古诗","c":["喔喔晨鸡唱，萧萧征雁鸣。","行装戒往仆，游子趣修程。","严风裂弊裘，霜气集冠缨。","亦知岁聿暮，奔走讵遑宁。","盼盼衣衢路，茕茕别友生。","鹡鸰傍我飞，枫树送我行。","商歌惨无欢，饮酒催尽觥。","车轮倏已远，宾客如晨星。","离别固可惜，志在身与名。","相期各黾勉，天路方清平。"]},{"t":"别内","f":"五言古诗","c":["秋霜凋女萝，夕露沾兔丝。","依依两夫妇，贫贱生别离。","思昔结缡日，适际离乱时。","布衣才掩胫，糟糠不充饥。","性拙命复穷，偃蹇世所嗤。","赖子同甘苦，孤贞常自持。","幸逢世道平，天路振羽仪。","欢爱未云竟，殷勤方自兹。","执袂讵忍分，清涕流裳衣。","淹留日月促，去去无归期。","晨鸡咿喔鸣，行李戒路岐。","仆从已严驾，安能更迟迟。","所嗟长辛苦，不为儿女悲。","遗语望邻曲，含酸望亲知。","恻恻重恻恻，此怀当告谁。"]},{"t":"代内赠别","f":"五言古诗","c":["恻恻重恻恻，君为远行客。","远行无时还，千山复万山。","不怨别离苦，所嗟道路难。","鸿雁集沙渚，鸟雀栖山樊。","遑遑欲何之，竟岁不得安。","昔为风中柳，今若霜后兰。","雪霰被平野，风沙侵苦颜。","苦颜日以凋，去路日以遥。","妾今守空闺，岁暮不自聊。","寒花无妍姿，冻柳无秀条。","凄其旧容色，坐为忧患销。","临期一樽酒，聊以永今朝。","前途善珍重，努力登云霄。"]},{"t":"寄郑进士毅德宏","f":"五言古诗","c":["步出城东门，豁我幽素怀。","茂树交绿柯，钟陵敞云崖。","有鸟鸣春树，顾声何喈喈。","静言感物理，心思寡所谐。","生念同门友，襟期旷以乖。","亨衢未接武，邱樊尚高栖。","王度今清夷，缙绅若云来。","鸣珂登凤阙，曳履上鸾台。","谁怜抱孤贞，甘分弃草莱。","朝吟小山篇，暮咏猛虎词。","会酬盍簪愿，天意谅不违。"]},{"t":"车驾游天界寺应制","f":"五言古诗","c":["车书浑文轨，海岳献嘉祥。","皇风载清穆，王度日隆昌。","开岁时丰庆，九域会冠裳。","璇文星再纪，五色日重光。","顺令下宸游，招摇随西行。","灵雨浥驰道，条风清太常。","万骑罗长云，千官沸鸣珰。","翠华旋地轴，黄道辟天阊。","绀殿开祇林，金莲灿上方。","百灵俨扈跸，龙象肃周行。","于时春始和，淑气播青阳。","卿云笼羽盖，瑞旭炫虹梁。","多士溢词林，侍从参翱翔。","玉音闻謦欬，御翰洒琳琅。","赓歌详舜训，文思粲尧章。","天颜穆以愉，清宴乐未央。","愿言敷圣泽，仁风被八荒。"]},{"t":"朝回呈诸阁老","f":"五言古诗","c":["承恩入翰苑，窃禄侍彤帏。","日月行黄道，玑衡耀紫微。","菲才忝下列，丹衷无由披。","凌晨陪稷契，日晏揖皋夔。","海岳方奠安，神人亦恬熙。","敛盖瞻銮驭，鸣珂集凤池。","遥望双阙门，飞觚切云霓。","交疏罗结绮，疏柳啭文鹂。","轻裾随风旋，绿树昼景移。","明良感嘉会，文物应昌期。","濯濯联华采，翩翩秀羽仪。","宣情寄芳藻，聊用颂清夷。"]},{"t":"贽翰林宋先生诸老","f":"五言古诗","c":["依依野田雀，本在桑榆间。","深林荫栖息，卑枝覆羽翰。","春风照九垓，阳和德泽宽。","翱翔霄汉上，乃得随鸳鸾。","群公圭璧才，盛世仕明君。","出入金门里，百辟同缤纷。","显宦极崇高，下顾念斯文。","惠然枉礼遇，揣己愧明恩。","际会信有时，感激复何言。","斐文谢嘉诲，久敬道弥敦。"]},{"t":"治县事作","f":"五言古诗","c":["讼庭敞公馆，牒诉日纷纷。","退食常少暇，吏牍苦长勤。","刻木对胥曹，皇华劳远宾。","清晨起坐署，日入未解绅。","出沐事宴游，聊用散我神。","云还幽谷曙，鸟鸣芳树春。","信美非久居，欲留嗟无因。","逝言谢簪绂，垂纶越水滨。"]},{"t":"送王给事南还","f":"五言古诗","c":["良时幸一遘，嘉运难再逢。","流序若飞电，倏忽岁云终。","羡子瑚琏器，林麓隐高踪。","适此徵俊彦，奋起惠家邦。","观光充上宾，恩礼赫以隆。","金门拜给事，百辟肃敬恭。","回翔忽敛翼，言归沧海东。","昔若云中凤，今若南飞鸿。","出处各有道，显晦讵能同。","微官惭苟禄，仰首慕清风。","文成德亦著，节立道斯崇。","愿言秉夙志，永保贞素躬。"]},{"t":"还山行","f":"五言古诗","c":["禽鱼不可友，出就斯人居。","迂才忤盛世，复此归敝庐。","投迹近逸民，振衣辞高衢。","白云绕我屋，清涧循我除。","深林挽云轩，松竹郁森疏。","贫家何所有，但有琴与书。","日暮无人来，浊酒聊自娱。","神全虑斯澹，妙得景亦俱。","岂不乐守贞，幽抱恒未舒。","屯膏违圣训，独善旷仁誉。","徘徊望嵩衡，恻恻怀居诸。"]},{"t":"拟古诗十九首 其一 行行重行行","f":"五言古诗","c":["歧路一尊酒，送君当远行。","交时未及竟，丝管激哀声。","冉冉岁华暮，悠悠云气征。","驰车戒往路，恻恻伤我情。","我情默已伤，欢爱不可忘。","昔为春花妍，今为秋草荒。","秋草荒有时，夫君见无期。","独宿坐长夜，泪落如绠縻。","白日傥回照，孤怀君所知。"]},{"t":"拟古诗十九首 其二 青青河畔草","f":"五言古诗","c":["青阳煦林薄，春气匝道周。","婉娈都人子，采桑南陌头。","修眉婉清扬，玉颜和且柔。","明妆照碧落，五马为久留。","久留谅奚为，妾非贵者俦。","贫守蓬蘧篨，献食独安羞。"]},{"t":"拟古诗十九首 其三 青青原上柏","f":"五言古诗","c":["置酒高堂上，宾友列长筵。","绮食罗雕盘，烹鳖脍熊蹯。","回风吹绣縠，悲管间清弹。","遗响妙入云，慷慨有馀欢。","流光若逝水，安得长驻颜。","薄酒聊斟酌，幽襟良可叹。"]},{"t":"拟古诗十九首 其四 今日良宴会","f":"五言古诗","c":["南园有佳人，窈窕桃李颜。","容华一何丽，顾盼生光妍。","进退礼自防，秉德幽且闲。","良媒候嘉意，君子希令言。","鸿雁念俦侣，关睢鸣河间。","盛年若流水，隐处独长叹。"]},{"t":"拟古诗十九首 其五 西北有高楼","f":"五言古诗","c":["华月散高树，列曜何参差。","流光射结绮，思妇惨中闱。","良人涉远道，感叹夜何其。","清声发妙曲，宛转有馀哀。","妙曲固可听，馀哀知为谁。","春至桃李妍，岁暮华色衰。","居然独处廓，顾影久徘徊。"]},{"t":"拟古诗十九首 其六 涉江采芙蓉","f":"五言律诗","c":["故人隔千里，寄我青琅玕。","琅玕色美好，爱重若邱山。","感兹缠绵意，将以遗所欢。","路遥不能致，欲插排风翰。"]},{"t":"拟古诗十九首 其七 明月皎夜光","f":"五言古诗","c":["离离谷中树，灿灿春华芳。","枝叶何盛茂，忽然随风扬。","流光有凋换，物理安可常。","扰扰路旁子，哀歌使我伤。","杪秋天气肃，白露结严霜。","揽衣不能寐，起视夜何长。","明月出东壁，众星罗纵横。","岁暮鶗鴂鸣，百草青自黄。","远道者谁子，驱车登太行。","太行郁嵯峨，天路无津梁。","兴言念同志，涕下沾我裳。"]},{"t":"拟古诗十九首 其八 冉冉孤生竹","f":"五言古诗","c":["青楼何高高，绮疏临道旁。","美人娱永夜，皓齿发清倡。","玉颜羞掩媚，妙曲婉成章。","含宫亦泛羽，忽复转徵商。","行云驻远汉，飞尘连虹梁。","识曲世所稀，遗音空飘扬。","歌竟夜阒寂，悠悠哀思长。"]},{"t":"拟古诗十九首 其九 庭中有奇树","f":"五言古诗","c":["洞庭木叶下，悲吹激微寒。","美人倚修竹，凝睇九疑山。","层云没远巘，轩车绝来还。","既怀文玉佩，复采澧水兰。","结言欲有赠，天路远险艰。","沉忧坐将老，岁月销令颜。"]},{"t":"拟古诗十九首 其十 迢迢牵牛星","f":"五言律诗","c":["北风吹雪霰，同云四垂阴。","惠而能好我，寄我瑶华音。","蟋蟀入床下，晨风飞北林。","川梁限楚越，思子阒伤心。"]},{"t":"拟古诗十九首 其十一 回车驾言迈","f":"五言古诗","c":["壮士悲白日，达人爱景光。","景光无停留，鬓发忽以苍。","严霜被野草，行旅思故乡。","禽鸟有所识，百蛩知潜藏。","如何不黾勉，老至空自伤。"]},{"t":"拟古诗十九首 其十二 东城歌且长","f":"五言古诗","c":["咸阳九原上，昔日冠盖场。","秋风动禾黍，旷野浩茫茫。","大化无停留，荣耀安可常。","烟云迷五柞，榛棘没长杨。","时运理则然，来者徒自伤。","所以放志意，酣歌称我觞。","鸣筝纵繁响，缓此幽思长。","回车长乐阪，将去复彷徨。","愿为云中雁，寥廓恣高翔。"]},{"t":"拟古诗十九首 其十三 驱车上东门","f":"五言古诗","c":["良辰集宾友，载酒登北邙。","百草何离离，高坟被山冈。","四野生悲风，夕日寒无光。","狐狸穴空圹，稚子觅亡羊。","人生寄一世，奄逝若朝霜。","高堂与大宅，终作荆棘场。","蓬莱隔弱水，仙说成荒唐。","及时且行乐，勿用徒悲伤。"]},{"t":"拟古诗十九首 其十四 去者日以疏","f":"五言古诗","c":["白日无流光，逝水无回波。","浮生类转烛，运尽归山阿。","松柏夹长路，高坟起嵯峨。","古来皆若此，咄咄将奈何。","谁弦雍门琴，和此薤露歌。"]},{"t":"拟古诗十九首 其十五 生年不满百","f":"五言古诗","c":["日月递朔望，推迁无时停。","鼎鼎百年内，所为竟何成。","贤者解斯理，达生外其形。","良辰有美酒，日对宾友倾。","迢遥阆风邱，奇树秀瑶英。","周王八骏没，天路杳溟溟。"]},{"t":"拟古诗十九首 其十六 凛凛岁云暮","f":"五言古诗","c":["江潭十月交，霜露萃郊原。","卉木无留荣，百草日夜乾。","鸿雁鸣洲渚，猿狖悲空山。","闺人念远道，抚节涕汍澜。","川梁一暌隔，魂梦夜不安。","厚爱君讵知，新恩忘前欢。","忠诚不见白，剖心良独难。","望望千里道，无由生羽翰。"]},{"t":"拟古诗十九首 其十七 孟冬寒气生","f":"五言古诗","c":["愁人起视夜，北斗低复昂。","中垣耀室壁，良月知载阳。","客行涉远道，葛屦履严霜。","愿欲同辛苦，江汉愁且长。","临风付书劄，鸿雁无来翔。","悄悄闺闱心，岁暮惟独伤。"]},{"t":"拟古诗十九首 其十八 客从远方来","f":"五言古诗","c":["妾有锦绣段，文采裁为衿。","上罗连理枝，下织双飞禽。","惜此嫁时物，珍之比南金。","良人隔山海，岁月亦已深。","愿因飞鸿翼，寄以表此心。"]},{"t":"拟古诗十九首 其十九 明月何皎皎","f":"五言古诗","c":["欢爱夏日短，忧愁春夜长。","房帷敞虚日，对此华月光。","薄寒凄以至，入我罗衣裳。","悁悁感心目，欲寂还不遑。","良人远行役，三载滞遐方。","别时木叶落，今已花卉芳。","无由达衷曲，怅望隔河梁。"]},{"t":"紫骝马","f":"古风","c":["紫骝马，黄金羁，妾家夫婿金陵儿。","金陵正值繁华时，日与游侠相追随。","追随游侠金陵下，长跨金羁紫骝马。","赌胜初登蹴鞠场，纵酒还来斗鸡社。","越罗楚练照晴空，飞鞚扬鞭去似龙。","却转端门回辇路，斜穿夹道过行宫。","行宫夹道通三市，长使旁人誇意气。","紫陌春融锦绣连，青楼日暮箫笙起。","青楼娼女砑罗裙，清歌宛转驻流云。","歌阑陌上春风度，舞罢楼前璧月新。","陌上楼前相识多，相陪相引屡经过。","房栊寂寞交疏里，云鬓妆成奈尔何。"]},{"t":"乌夜啼","f":"七言古诗","c":["茏葱窗闭云凝影，织锦梭停蜀丝冷。","兰心欲语还自缄，待郎不来秋夜永。","秋乌夜夜啼哑哑，凤书应来郎到家，开门自把枇杷花。"]},{"t":"望行人","f":"五言古诗","c":["高楼临广路，朝日丽绮疏。","美人盛容饰，凝涕倚踟蹰。","踟蹰长太息，愁思郁烦纡。","愁思知何为，自言惜离居。","将期岁暮返，忽历三载馀。","昔如春园花，今若秋水蕖。","盛年讵可再，独宿谁与娱。","思逐北风翔，相从千里馀。","中途傥相失，浩叹何所如。"]},{"t":"长相思","f":"古风","c":["洞庭清秋灏气多，金盘彩月摇碧波。","湘灵朱丝奏云和，九疑木落风娑娑。","长相思，渺何极。","湘山云断湘水深，泪竹年年雨花碧。"]},{"t":"饮马长城窟行","f":"五言古诗","c":["长城去迢迢，征马鸣萧萧。","马饮月窟水，长城万里遥。","征人行从军，离家今已春。","春花复秋草，闺人念远道。","远道归无期，漂流不相知。","徘徊复辗转，辗转长相思。","相思不相见，涕泪铅华滋。","风从西北来，吹我井上桐。","寒凉飒将至，恻恻伤我衷。","乘月捣寒衣，丁丁砧杵悲。","衣成欲寄远，君在天一涯。","瘦马恋破枥，倦禽思故巢。","君行亦已久，孤妾宁自聊。","远使来长城，带得音信还。","书中何所道，但道寄平安。","平安不顾返，岁月忽已晚。","君心知若何，妾意今无限。"]},{"t":"行路难","f":"古风","c":["君不见翟公昔时作廷尉，蝉联宾客填门至。","并披缝掖曳长裾，夕振鸣珂昼停骑。","峨冠博带称往古，吐气扬眉论当世。","交态浑如金石坚，朋情肯数芝兰契。","当时意气何豪雄，炙手可热嘘生风。","日晏联镳登紫阁，平明骑马出铜龙。","只道浮华长若此，谁云生死不相从。","一朝官罢成索寞，门外庭前可罗雀。","寂寂蓬居向午开，萧萧木叶惊秋落。","古来此道今可悲，须知荣悴亦无时。","花前且尽一壶酒，世事悠悠侬不知。"]},{"t":"行路难","f":"古风","c":["龙门西接昆仑邱，中有一带黄河流。","风雷喷薄不可以利涉，鬼浪吐雪龙为愁。","我行欲济无方舟，长吟泽畔成久留。","暮天摇落对羁客，白石楚楚青枫秋。","行路难，岁将夕。","灵槎八月秋风生，安得乘之溯空碧。"]},{"t":"白头吟","f":"古风","c":["妾昔深闺里，风情未尝识。","独有如花容，婵娟自怜惜。","愿言嫁得同心人，共驾双飞彩鸾翼。","君时走马从东来，扬眉吐气万人开。","当时鸿雁岂无侣，妾独怜君英俊才。","一夕误逾垣，从君共君语。","君指松柏枝，岁寒永相许。","从君衣锦还故乡，蓬屋萧然但环堵。","相守在贫贱，栖栖还共居。","自除花压面，起结青罗襦。","当垆涤器不知耻，迟君他日乘高车。","一朝意气题桥柱，偶上金门见明主。","十年词赋发成丝，纵博黄金只如许。","才华备供奉，富贵能几何。","文园病消渴，憔悴亦已多。","金茎瑞露不得赐，起视云汉空星河。","不谓羁旅馀，向来聘私室。","旧好如尘埃，新情若胶漆。","清晨起坐白头吟，哀怨凌天薄云日。","哀怨复哀怨，娥眉空自颦。","生来见事晚，怨妾不怨君。","投珠掷璧不自惜，晚节末路当何云。","妾已无复言，于君更何道。","愿君与新人，欢爱永相保。","莫贪春日兔丝花，亦作秋霜女萝草。","妾有青铜镜，蛟螭蟠玉台。","自君一为别，弃置生浮埃。","志殊心异不在貌，珠帘绣匣宁劳开。","案上龙唇琴，冰弦冷将绝。","悲来试一弹，不觉泪成血。","因君一曲凤求凰，误妾凄凉百年月。","浪荡指明月，清光无定时。","君心亦如此，中路岂不移。","妾心怀冰霜，凛凛君讵知。","君心傥有能回日，缺月重圆应可期。"]},{"t":"昭君叹","f":"七言古诗","c":["忆初少小入宫时，风鬟雾鬓绿萎蕤。","自言佳色已无匹，不谓官家犹未知。","十二琼楼动光彩，三千彩女妒娥眉。","鸳帏不作春宵梦，红叶常题秋日诗。","画工不识嫣妍趣，却遣丹青故相误。","买工不是吝黄金，黄金已尽相如赋。","早知容貌世稀有，临别夫君犹可顾。","翻将寂寞倚门悲，啼向迢迢去乡路。","穹庐雪落似梨花，五月天山草未芽。","镜玉尘昏孤凤影，臂红香冷守宫砂。","长门无复沾恩泽，绝域谁知有岁华。","不恨胡沙埋绝色，还闻汉国选良家。","人言北狩封姑衍，尽日凝妆候金辇。","憔悴虽缘别恨添，娉婷尚胜良家选。","五云迢迢山宛宛，日近长安一何远。","新爱虽浓独自怜，旧恩未断谁能遣。","琵琶一曲苦从军，调苦单于醉不闻。","霜压氍毹秋欲半，月低弦索夜将分。","溶溶泪湿龙香拨，冉冉愁看雁塞云。","病里常思霍去病，梦中犹诅奉春君。"]},{"t":"湘妃曲","f":"五言古诗","c":["沅江木叶下，洞庭秋水多。","湘灵美清夜，隐约倚层阿。","冰雪耀玉容，远山敛翠娥。","风鬟散香雾，美盼溢回波。","明珰结珠佩，绞绡夹素罗。","金支色璀璨，翠蕤光荡摩。","小环奏玉箫，双成鼓云和。","瑶管杂哀怨，清弹间啸歌。","妙曲随风扬，馀音泛流霞。","林端舞鸾鹄，水际起蛟鼍。","问汝何所思，慨叹慕重华。","轩车去杳邈，黄陵起嵯峨。","汀洲生蘼芜，松柏挂女萝。","清涕下洒竹，斓斑隐成花。","日暮天气肃，星移岁蹉跎。","灵荃不可见，婉娈悲如何。","九原傥可作，千载复来过。"]},{"t":"阿娇怨","f":"七言古诗","c":["妾昔初入昭阳时，横云学得内家眉。","风鬟雾鬓在君侧，长恃娉婷不自持。","侍宴前楼春烂熳，承欢别殿夜逶迤。","西凉弦索龙香拨，北苑葡萄金屈卮。","一从宠薄恩光歇，长门永巷喧呼绝。","斗帐香销豆蔻垂，舞裙宽褪丁香结。","熏笼夕倚琐窗雨，罗袜秋凌玉阶月。","凄迷梦醒心似灰，零乱忧来涕如雪。","横塘浦口大堤边，女伴年年忆采莲。","双飞翡翠浑如画，并蒂芙蓉只似仙。","傍舍谁吟白华曲，下堂长咏绿衣篇。","君恩若许重相惜，缺月清光应再圆。"]},{"t":"班姬怨","f":"五言古诗","c":["燕燕复燕燕，飞来尾涎涎。","朝辞乌衣国，暮入昭阳殿。","羽毛一何好，似许令侬羡。","遂令同辇人，咫尺不相见。","新爱易旧欢，物情有迁变。","白日尚移光，君恩讵能遍。","怀今思独永，感昔泪如线。","秋草沿玉阶，流尘满纨扇。","纨扇知妾心，携持自障面。","时来即所遇，势失贵亦贱。","庭树秋风生，无劳匣中怨。"]},{"t":"乌孙公主歌","f":"古风","c":["咽咽复咽咽，羊车凤辇恩光绝。","新新复新新，驼裘貂帽来相亲。","昔为花月汉宫女，今作风沙胡地人。","汉宫胡地何分别，人生过眼如一瞥。","彩云易消月长缺，奈何婵娟涕如雪。","且喜华夷罢战争，天南天北乐升平。","一堆红粉垄头葬，百万儿郎边上生。","汉宫剩有三千女，岂惮边庭有强虏。","从此龙泉不用磨，但从天下选娇娥。","银鞍白马金橐驼，琵琶弦索声相和。","葡萄酒绿朱颜酡，婿家儿孙日日多。","年年只报烽火息，莫问婵娟伤绮罗。"]},{"t":"团扇词","f":"古风","c":["团扇复团扇，秋风淅淅昭阳殿。","燕燕飞来尾涎涎，同辇夫君不相见。","长信宫深秋夜长，玉阶坐对明月光。","玉绳低垂夜未央，牵牛织女度河梁。","自投长袂数愆殃，梦魂仿佛若有亡。","夫颜梦见在我旁，觉来邈若天一方。","起援鸣筝发清商，旧怨未平新怨长。","新怨未平复旧怨，怨此衔泥梁上燕。","双飞双宿令人羡，还来啄人嘴如箭。","燕燕于飞奈尔何，閒愁不为伤绮罗。","长陵百尺高嵯峨，山精日落悲薜萝。","谁能为谱螽斯羽，翻作当筵白纻歌。"]},{"t":"挂剑台","f":"古风","c":["我有白虹青霜之宝剑，舞时烨烨莲花艳。","去年北上东蒙峰，君眼如猫看不厌。","今年匹马归江东，将期豁我抑郁磊落之心胸。","怀君不见泪如水，坟树索索生秋风。","岁华露落对杯酒，酒酣脱剑为君寿。","今为君赠君不知，坟前挂向桂树枝。","等死酬知心所许，剑有神灵剑应语，金环鱼肠宁足数。","草平翁仲月荒凉，山鬼提携学吾舞。"]},{"t":"铜雀台","f":"古风","c":["阿瞒在时起台殿，宰割山河几征战。","赋诗横槊气何雄，卖履分香泪如霰。","良辰吉日人自悲，安有繁华非昔时。","华容熳舞对松柏，歌笑喧喧知为谁。","有歌有舞还尚好，莫怨西风翠蛾老。","君不见柏梁废榭无人登，烟草凄凄茂陵道。"]},{"t":"杨白花","f":"古风","c":["杨白花，花离离。","随风化萍草，荡漾无还期。","仙桃醉日氍毹暖，荔枝浆冻黄金碗。","连臂歌残翠华馆，愁来玉环低款款。","春宵长，春宵短。"]},{"t":"休洗红","f":"古风","c":["休洗红，洗红颜色落。","莫思君，思君怀抱恶。","君恩原不浅，妾命由来薄。","君如白日不回光，妾有芳情向谁托。","休洗红，洗红生寂寞。"]},{"t":"苦寒行","f":"五言古诗","c":["隆冬十二月，四野云气浮。","寒日霾夕光，层阴肃幽幽。","苦哉离家人，岁晏尚远游。","北上太行阪，屈结阻且修。","西辕指张掖，东辙望幽州。","严风裂短袂，密雪凋敝裘。","熊罴啼路隅，鬼火照林陬。","车毂陷泥滓，马毛冻飕飗。","涉险终日行，薄暮不得休。","苦颜带冰悄，涕泪沿眶流。","空山绝人烟，野饭依古丘。","行囊已罄尽，何以慰旅愁。","苦哉离家人，坐念生百忧。"]},{"t":"鞠歌行","f":"五言古诗","c":["荧荧圃中花，濯濯堤上柳。","春日齐敷荣，秋至就衰朽。","万物随变化，浮生讵永久。","自非彭与聃，谁能长寿考。","君看少壮颜，倏忽成老丑。","及时当黾勉，迟暮复何有。"]},{"t":"伤哉行","f":"五言古诗","c":["长夜何漫漫，秋气凄已悲。","浮云掩明月，凉风吹我衣。","曳履出房帷，鸣佩下重阶。","俯观霜露集，仰视星宿稀。","倦鸟止复翔，百虫鸣声哀。","飞翻念俦侣，呻吟知岁时。","感兹时物变，恻怛伤我怀。","谁能驻流光，息此心所思。"]},{"t":"懊恼曲","f":"五言古诗","c":["妾家良人婿，执戟明光里。","四时迁显官，宠幸无与比。","似妾初嫁时，容光照邻里。","芳荣有衰歇，喧赫讵可恃。","火热变灰寒，懊恼何时已。"]},{"t":"长安篇","f":"五言古诗","c":["长安形胜地，京华富才雄。","北开左冯翊，南列右扶风。","汉道方全盛，象魏何穹窿。","逶迤长乐阪，壮丽未央宫。","游侠多少年，娇女秀华容。","凌云飞甲第，照日辉帘栊。","行乐正及时，绮罗绣茏葱。","珠叶摇蝉鬓，银鞍被玉骢。","千花色炫烂，万柳景昭融。","击鞠东门外，斗鸡驰道东。","青楼启夕月，瑶筝沸春空。","良时逝不留，流连曾有终。","且极娱心意，无为虚光风。"]},{"t":"上京行","f":"五言古诗","c":["京华全盛日，江南钜丽时。","凤阁凌天翥，雕甍向日披。","堤柳垂宛转，沟水远逶迤。","万国年方泰，三阳景载熙。","少年纵娱游，游侠相追随。","载酒联丝络，乘骢鞚玉羁。","斗鸡初赌锦，击鞠复争驰。","百卉照眼明，步障随风移。","珍禽哢幽响，咬嘎一何悲。","日暮宴青楼，称觞侑琼姬。","开筵列上客，急管闻哀丝。","为乐殊未央，但惜白日攲。","豪雄极志意，黄发以为期。"]},{"t":"采莲曲","f":"古风","c":["江南好采莲，莲叶何田田。","鱼戏莲叶下，鸥飞莲叶边。","莲叶莲花耀洲渚，桂楫兰桡下长浦。","采莲采叶忘采花，隔水停船共君语。","君语不还顾，妾心将奈何。","回船向明月，月照江水波。","江水照妾影，明月知妾情。","郎心得似此明月，兼照莲花与莲叶。"]},{"t":"长歌行","f":"古风","c":["弹鸣弦，发清商。","悲吹激林木，歌声一何长。","歌声长，弦声缓，百年鼎鼎不易满。"]},{"t":"古意二首 其一","f":"七言绝句","c":["山樊花落春风起，吹妾芳情渡湘水。","梦中蝴蝶相交飞，门前鹊声郎马归。"]},{"t":"古意二首 其二","f":"七言绝句","c":["梧桐初落金井床，断蛩声里月如霜。","沉沉玉漏清秋夜，妾颜如花恐愁谢。"]},{"t":"秋风词三首并序 其一","f":"七言古诗","c":["秋风袅袅天意晶，寒虫唧唧霜露零，白云孤飞雁南征。","念君岁阑远游行，长年驱驰竟何成，闺阁盼望空荧荧。","哀来伤秋百感生，感极涕泪沾衣缨。","何人月高弹鸣筝，繁弦急丝搅离情。","银河横天湛空明，哀猿寥寥共凄清。","微禽安栖夜不惊，夫君胡为未遑宁。"]},{"t":"秋风词三首并序 其二","f":"七言古诗","c":["秋风飒飒林木空，吴山楚山千万重，湛湛江水上有枫。","念君游行远从戎，不遑宁居走西东，寂寞空闺敞房栊。","独宿涕泪沾襟胸，怅望不见忧怔忡。","长云遥天叫孤鸿，哀音嗷嗷思无穷。","黄姑斜河夜正中，牵牛七襄淡横从，夫君胡为苦匆匆。"]},{"t":"秋风词三首并序 其三","f":"七言古诗","c":["秋风淅淅庭宇虚，日行南陆露如珠，江空木落芳岁徂。","念君远游今何如，别离不得尺素书，妾久悲伤惜居诸。","恻恻涕泪盈衣裾，凝思关山倚踟躇。","南邻谁家吹笙竽，清声撩人思烦纡。","繁星丽天明月孤，城头夜栖白头乌，夫君胡为未宁居。"]},{"t":"南浦曲","f":"古风","c":["君家住南浦，妾家住横塘。","少小曾相识，况复是同乡。","妾年与君相上下，月下花前几相许。","相怜相爱君不知，却共何人隔花语。","芙蕖被霜那得连，荷风荡露那得圆。","君情君意苦难定，妾貌妾心常自怜。"]},{"t":"横塘曲","f":"古风","c":["莺黄不染衣，蝶粉不匀面。","有情翻作无情悲，相见浑如不相见。","落花深处紫骝嘶，红藕香中画舫移。","藕丝难叠同心结，花影空成连理枝。","君如呼沙鸿，妾似浮波雁。","暂时照影相和鸣，逐浪随风各分散。","分散杳然去，几时还合并。","芙蓉易谢月常缺，亦似人间离别情。"]},{"t":"春愁曲","f":"古风","c":["妾意一何长，春光一何短。","良人游冶郎，去去不知远。","含桃石竹花尽红，房栊蝴蝶醉春风。","令人翻爱远离别，孤绝相思情更浓。"]},{"t":"春开曲","f":"七言律诗","c":["去年百花开春风，妾颜窈窕如花红。","今年花色仍自好，妾颜比花已渐老。","良人新爱移平生，妾貌如花空复情。","花开无言妾不语，妾泪长垂花带雨。"]},{"t":"游丝曲","f":"七言古诗","c":["游丝映户春风荡，雕檐雨挹踟蛛网。","春花亦笑绮帐空，故遣飞红入虚幌。","青楼夫婿醉忘归，魂梦相寻意转迷。","恍似妾心怀旧爱，还如君意恋新栖。","绮疏鹦鹉通人语，戏把枇杷掷金羽。","含情暗卜无心负，今夜渠侬到家否。","游丝罥花风叶叶，吴罗袷薄新寒怯。","蜂游亦解钻绮疏，不独房栊出蝴蝶。","怀人不为青春过，别有閒愁幽思多。","君情妾意俱肠断，旧爱新怜奈尔何。"]},{"t":"落花曲","f":"古风","c":["昨日见花开，今日见花落。","花落花开还满枝，人老终无年少时。","劝君及时且行乐，莫管花开与花落。"]},{"t":"木叶曲","f":"古风","c":["南风木叶青，北风木叶黄。","木叶有零落，客心与尔同悲伤。","悲伤日日人惭老，明年木叶依旧好。"]},{"t":"莲花曲","f":"古风","c":["莲花复莲花，莲花相交加。","叶如云鬓偏宜绿，花比妾容还更佳。","莲叶莲花相对好，妾容妾鬓愁中老。"]},{"t":"葵花曲","f":"七言古诗","c":["蜀葵花开开复落，黄金满地秋风恶。","良人远去不归家，秋风吹落蜀葵花。","蜀葵花落开复好，良人不归愁欲老。"]},{"t":"鸳鸯篇","f":"古风","c":["南浦双鸳鸯，生来不独宿。","叶底已双飞，花边还对浴。","鸳鸯可羡复可怜，况妾容华方少年。"]},{"t":"织妇词","f":"七言古诗","c":["吴中白纻白如霜，春风入衣兰麝香。","二月城南桑叶绿，新蚕初出微于粟。","采桑日晏携筐归，夜半悬灯待蚕熟。","缫成素丝经上机，两日一匹犹苦迟。","织成裁衣与郎著，妾宁辛苦教郎乐。","家中贫富谁得知，郎无衣著他人嗤。"]},{"t":"古镜词","f":"七言古诗","c":["贫女池边得铜镜，邻媪欢呼喜相庆。","持归铅粉三日磨，龙影模糊面犹瑩。","机中剪素为镜囊，染丝绣作双鸳鸯。","横看竖照心不厌，借插金钗学上堂。","废铜虽旧惜于宝，无钱买新旧亦好。","谁识青楼金镜开，珍珠缀匣琼为台。"]},{"t":"渔父词","f":"古风","c":["顺流得鱼易，逆流得鱼难。","难易有天定，顺流心所安。","网罗疏疏钓曲直，老翁取鱼兼取适。"]},{"t":"樵父词","f":"古风","c":["清晨腰斧出，日暮腰斧入。","青青遍原野，造化若不息。","我愿严霜杀荆棘，苍松翠柏高千尺。"]},{"t":"田家欢","f":"七言古诗","c":["田家养牛如养龙，妻孥望岁长防冬。","耕田得暇缚屋茅，编竹著泥防北风。","山田不雨水欲涸，田头水车鸣角角。","归来夜半犹未眠，新妇悬灯照蚕箔。","田家作苦无休时，夏来粜谷春卖丝。","无因昨夜到城郭，羡杀狂游轻薄儿。"]},{"t":"耕父词","f":"古风","c":["朝耕山下田，暮耕山下田。","辛苦食筋力，持此终岁年。","耕田得谷岂不乐，但愿年丰莫作恶。"]},{"t":"耕牛词","f":"古风","c":["朝出牛亦出，暮归牛亦归。","牧牛如种树，贵在不扰之。","放牛散食山下草，草香水甜牛易饱。"]},{"t":"射雉词","f":"古风","c":["春雉巢草中，子母不相离。","时时引子嬉，翅短还堕池。","回弓落箭不射之，深山大泽从汝飞。"]},{"t":"射虎词","f":"古风","c":["射羊得羊食，射虎被虎伤。","始知学射虎，不如学射羊。","村前村后腰我弩，但愿逢羊莫逢虎。"]},{"t":"采菱曲","f":"古风","c":["朝游大堤口，暮泛横塘边。","红粉照绿水，自羡还自怜。","红妆照水人见好，涉江采菱何可道。"]},{"t":"石榴词","f":"七言绝句","c":["累垂累垂复累垂，累垂压倒珊瑚枝。","西风擘破玳瑁皮，露出数颗珍珠儿。"]},{"t":"采莲词","f":"古风","c":["谁家游冶郎，日日在横塘。","只采莲叶绿，不采莲花香。","采莲采叶犹自可，怜新弃旧愁杀我。"]},{"t":"贫女叹","f":"古风","c":["寒花难为红，贫女难为容。","萧条镜中影，寂寞林下风。","蛾眉翠黛谁家女，日日东邻教歌舞。"]},{"t":"广州歌","f":"七言古诗","c":["广南富庶天下闻，四时风气长如春。","长城百雉白云里，城下一带春江水。","少年行乐随处佳，城南南畔更繁华。","朱楼十里映杨柳，帘栊上下开户牖。","闽姬越女颜如花，蛮歌野曲声咿哑。","□峨大舶映云日，贾客千家万家室。","春风列屋艳神仙，夜月满江闻管弦。","良辰吉日天气好，翡翠明珠照烟岛。","乱鸣鼍鼓竞龙舟，争赌金钗斗百草。","游冶留连望所归，千门灯火烂相辉。","游人过处锦成阵，公子醉时花满堤。","扶留叶青蚬灰白，盘饤槟榔邀上客。","丹荔枇杷火齐山，素馨茉莉天香国。","别来风物不堪论，寥落秋花对酒樽。","回首旧游歌舞地，西风斜日淡黄昏。"]},{"t":"草书歌赠颜景明隐者","f":"七言古诗","c":["钟王去我忽千岁，字体变怪少复真。","虫文鸟迹久不见，尘姿俗态空纷纷。","迩来继者谁独步，前有秃张后醉素。","词林秘府顷见之，令我啧啧生远慕。","君家此本尤清妍，神奇老笔真可传。","颓墙败壁霹雳死，枯桧古柏蛟龙缠。","秋蛇春蚓未易得，见尔为尔重嗟惜，宝之不翅圭与璧。","烦君收取谨护藏，莫遣风雷化真迹。"]},{"t":"智空和尚种松歌","f":"古风","c":["老僧种松如松柳，封植不知年岁久。","寒梢未解蟠穹苍，已见郁律蛟龙走。","焚香展席坐松阴，白石清泉清道心。","虚无自有神鬼会，风雨不妨猿鹤吟。","老僧与松有深契，浮华净尽存实际。","岁寒不受冰霜欺，静隐山中阅人世。","亭亭只作如是观，松年僧腊俱高寒。","夜深滕六雪中立，日落山精林际看。","老僧爱松如骨肉，不比枯梅与瘦竹。","君不见人间艳阳枝，春尽飞花满岩谷。"]},{"t":"题皇甫文远所藏左司郎中堵炳山水歌","f":"七言古诗","c":["繁花孔翠时共喜，金膏空青人罕识。","每观皇甫先生图，令我感此三叹息。","墨樵避俗如避鸮，折简但见先生招。","乱云团成树宛宛，澹墨扫作山迢迢。","人言此是云谷底，武夷下映九曲水。","不然五老匡庐峰，万叠芙蓉照彭蠡。","低低茅屋溪涧滨，墨樵更写先生真。","千章古木一藜杖，毛骨自是仙中人。","尘缘净尽丹砂熟，苍虬停飞虎亦伏。","山童卷取琅函经，纵有黄庭不须读。","烟霞此乐真不迂，临风却作长嗟吁。","十年未得还初服，蕙帐石室今何如。","先生归来早卜筑，我亦同栖此山曲。","便烦作赋邀墨樵，更与泉南数竿竹。"]},{"t":"虹县行","f":"七言古诗","c":["虹亭村落如秋花，十里五里方一家。","山城县治开草野，草屋低窄旋桑麻。","丁男当官应徭役，妇女看家种山麦。","汴沟淤塞无稻苗，麦足家家黍为食。","野桑养蚕收茧丝，枣根染丝来作衣。","秋湖水落莲芡盛，腊月雪深鹑兔肥。","岁时浇酒五月暮，但愿开云雨如注。","蚕成麦熟官事闲，柳堤人唱桑阴树。"]},{"t":"平原行","f":"七言古诗","c":["古原县郭如荒村，家家草屋荆条门。","自罹丧乱新复业，千家今有一家存。","稚子采薪割蒿草，妇女携筐拾梨枣。","丁男应役不在家，长驾牛车走东道。","黄河水涸无鱼虾，居人七月方食瓜。","人烟星散不成集，棠梨苦叶烹为茶。","凌州九月官税促，黍子在田犹未熟。","春霜夏旱蚕事空，不卖新丝卖黄犊。","银河七夕如水流，明年麦好君莫愁。"]},{"t":"平原田家行","f":"七言古诗","c":["零星矮屋茅数把，散住榆林柳林下。","磊墙遮雪防骤风，妇女颓垣拾砖瓦。","黄牛买得新垦田，土戟犁浅牛欲眠。","古河无水挂龙骨，自萦蒲绳探苦泉。","山蚕食叶黄茧老，野火烧桑桑树倒。","四畔灵鸡喔喔啼，九月霜风落红枣。","春丝夏绢输税钱，木绵纺布寒暑穿。","放舂黄米为新酒，学唱货郎为管弦。","平田旱多麦少熟，杏尽梨枯惟食粟。","衣粗食恶莫用悲，犹胜北军离乱时。"]},{"t":"碌碌行寄保昌县丞童豫","f":"古风","c":["碌碌复碌碌，驰驱半世为斗粟。","去年腊尽江左边，今春又驾江南船。","家贫每畏别离苦，不知携累还颠连。","炎云四月关门道，青泥滑滑杂流潦。","黄梅雨里钩辀啼，瘦妻前僵子后倒。","君时相见能相怜，自出床头官俸钱。","东家蹇驴觅借我，使我枯槁回春妍。","贫贱结交常草草，多难逢君识君好。","不得与君长周旋，关门长望令人老。"]},{"t":"飞仙归来词题武林朱以方招鹤轩","f":"楚辞体","c":["飞仙兮归来，无徘徊乎临皋。","蜀江雪落滩嘈嘈，潜龙起舞风怒号。","霜明赤壁山月高，琼琚仙翁魂梦劳。","飞仙兮归来，无容与乎青田。","春龙破玉耕紫烟，群仙环佩声锵然。","思乘逸响盘九天，羽衣不得长蹁跹。","飞仙兮归来，无留恋乎高轩。","华衣巍冠多祸愆，漳河之水流潺湲。","商都绿草生芊绵，崇居广厦不可以久延。","飞仙兮归来，无嘹唳乎华亭。","琳琅金薤惭世英，文章锦绮身后名。","终古白璧多青蝇，三吴云间不可以久宁。","飞仙兮归来，无浩荡乎辽海。","离家一去三千载，蜃气罡风晦文采。","华表凌寒欲谁待，城郭如故人民改。","飞仙兮归来，归翱翔乎馀杭。","武林水绿山青苍，海潮八月来钱塘，潮头白马神龙骧。","西湖凯风菱芡香，三高琪树可以栖玄裳。","飞仙兮归来，归同隐于越山。","临清屠苏云半间，晴窗月榭开雕阑，画楹翠筠玉珊珊。","素琴鸣丝朝罢弹，匏尊浊酒可和颜。","衣汝以五彩之春云，食汝以百斛之琅玕。","轩庭不惊乐且闲，飞仙归来莫盘桓。"]},{"t":"晚发英德","f":"七言律诗","c":["山城斗大临江横，数椽茆屋炊烟青。","炎风吹林桂花落，斜日倒影沧江明。","沧浪万顷舟如叶，舟子齐桡歌激烈。","一篙新水静悠悠，今日江头雨初歇。"]},{"t":"赠端孝思","f":"七言古诗","c":["端郎白皙如冠玉，葩辞丽藻撑满腹。","生来未作九品官，声价蚤已惊流俗。","阿翁旧日尚书郎，出领方镇专衡湘。","掖垣休暇会宾客，冠带楚楚盈华堂。","怜君三十犹未娶，却向穷檐守章句。","纷华满目何足云，昔者炎门今不遇。","杨花三月石城西，翠袖红裙满大堤。","良辰欢笑暂行乐，永夜索寞犹孤栖。","兴来呼酒秦淮屋，宣州雪梨如碧玉。","坐中北客为燕歌，歌得前朝数般曲。","看君颜面人中英，暂时逊缩非避名。","凤雏未必老丹穴，谢安亦岂忘苍生。","玉堂学士龙门叟，日日谈君不容口。","振翮青云谅匪遥，与君且尽杯中酒。"]},{"t":"赠高彬","f":"七言古诗","c":["高彬魁梧身七尺，秀眉丰颊盈广额。","几年共食越江鱼，此中同作钟陵客。","钟陵上国要路津，出门大道连青云。","交游脱略旧时辈，拜揖尽是英豪人。","小年一字都不识，近日能诗兼读易。","看君意志肯如此，世人见者谁不识。","平生于我最知己，旅邸浮沉托生死。","得钱慷慨即相赠，归家不问妻与子。","玉壶美酒桃花春，酣歌每到清夜分。","冲人侠气俨郭解，不信穷愁如有神。","人生穷达何足道，微名于世须亦早。","但怜零落故山云，未得相从逐幽讨。"]},{"t":"送何三元帅北上","f":"七言古诗","c":["春风吹花江水波，江头杨柳绿差差。","临歧送别增慷慨，我与何郎情最多。","何郎昔年十六七，明珠虎符光照室。","锦臂苍鹰掣暮云，青丝白马嘶晴日。","此时我作座上宾，星楼月帐长相亲。","班超英杰耻投笔，孙楚兀傲犹参军。","何郎严亲初入觐，何郎笑解封侯印。","鹊血弓弰满壁悬，青门瓜地从人问。","今年会晤蒋陵西，烂熳莺花醉欲迷。","梧桐叶落凤台曲，杨柳烟笼白下堤。","何郎于我情最厚，此别宁堪酌春酒。","平原北上路迢迢，白雁南还寄书否。"]},{"t":"题昭阳草堂手卷为增城县丞谢英赋","f":"七言古诗","c":["太傅风流一千载，乌衣朱雀今谁在。","何时文水见文孙，玉树亭亭继光彩。","茅茨还枕小东山，山下银溪玉作湾。","不独澄江静如练，金屏想像如花颜。","陂塘别墅恣情适，荡漾寒波映空碧。","隐隐疑闻躐屐声，青青似带罗裙色。","罗裙翠带总相宜，君家兄弟况能诗。","细雨蛙声来座席，淡云疏影落涟漪。","南陲作郡无复意，那更旁人知许事。","讼庭窄狭临溪水，日倩鸥群伴清致。","清梦迢迢若个边，鸣蜩初变柳盈园。","咏歌未必惭康乐，俊秀真堪比惠连。","惠连别来年岁久，梦里知能相见否。","且停忆草远生愁，便可巡池酌春酒。","伯仲联翩圭组才，声名远播凤凰台，暂时分手何有哉。","行当连袂赴青琐，莫学柴桑归去来。"]},{"t":"题高彬白云山房手卷","f":"七言古诗","c":["高彬昔年喜学武，七尺长躯力如虎。","往昔追强过营门，日来从戎事藩府。","锦袍白马金连钱，骑将校猎城南边。","鼻头火发不知热，耳后风生犹著鞭。","秦楚山川岁华改，万人零落惟彬在。","腰间不插黄金符，却向词林学文彩。","白云远在藩府阴，彬驰匹马恣幽寻。","秦台古树挂秋色，远涧流泉清客心。","娱游日夕欢不足，更傍山腰结茅屋。","多种琅玕引凤凰，大开门径邀麋鹿。","雨龙归洞白云间，叆叇绵联窗户间。","月映馀辉长不夜，云拖晻霭似巫山。","山中白云如白石，高彬与云同枕席。","云来万树似开花，云去千岩同一色。","何年作客帝王州，却按新图忆旧游。","红树不知淮水晚，白云遥认故山秋。","故山白云长自好，且莫看云被山恼。","他年谢病解朝衣，我亦从君拾瑶草。"]},{"t":"会乡友","f":"七言律诗","c":["京城客至沽新酒，旅邸萧条百无有。","秦淮钓得槎头鳊，旋学吴中脍鱼手。","此时怀抱同君开，况有同门故旧来。","醉里时忘蒋陵道，梦中犹记越王台。"]},{"t":"送张仲庸归陕西","f":"七言古诗","c":["虹亭腊月天欲雪，洪州旅客归心折。","秦关远在黄河西，行李萧萧待明发。","忆昔长安全盛年，君骑白马锦鞍鞯。","五陵花月映红袖，京兆春风摇玉鞭。","年光去去如流水，华发栖迟簿书底。","却随征雁向南云，三载离家数千里。","浮云往事复谁论，近喜天书出午门。","垂帘事简得休暇，归访商颜山下村。","归歧送君饮君酒，五女峰头握君手，壮君行色百无有。","明年二月君到家，寄声为道平安否。"]},{"t":"异橘图","f":"七言古诗","c":["宪郎高隐林泉日，种得江南几株橘。","春日荧荧吐瑞花，秋风磊磊悬嘉实。","去年起作京华游，台端六月如九月。","乌啼翠柏玉柯冷，鹤唳璧山琪树秋。","归来风景慰吟目，依旧繁阴盖书屋。","万颗重垂丹井黄，千头再结龙洲绿。","绿映红稀压四邻，洞庭隐映波粼粼。","羲之帖就霜凝笔，巴叟棋敲香满身。","广文有才过屈宋，解撰王孙楚声颂。","烦君采摘笼白鹅，载酒谈玄作清供。"]},{"t":"桑梓图为左布政徐本赋","f":"七言古诗","c":["君侯早岁逢间关，声名出镇三楚间。","江湘霖雨起诸葛，环堵苍生思谢安。","忧时两鬓飒犹绿，捧日孤衷明独丹。","笑挥霜箑向戎垒，倒挽银汉清八寰。","功成入奏麒麟殿，中外好官扬历遍。","才华已羡冠西曹，丰采还来照方面。","荔枝香凝粉署戟，桄榔影入薇垣甸。","凭高作赋羡才华，拄笏看山忆乡县。","乡县迢迢路几千，齐安远在长江边。","石牛青嶂接巴蜀，螺湖绿水通湘沅。","鸥飞竹楼笑傲吏，鹤过赤壁怀诗仙。","回廊忽披生色画，一幅鹅湖万金价。","书屋斜连洛浦阴，渔船暝泊临皋下。","天低故垄锁松柏，秋入平田熟禾稼。","征帆去住却无情，王事鞅掌何由暇。","皇恩诏锡许归荣，稚子牵衣父老迎。","更植社莲招惠远，添栽径菊学渊明。","香醪再泼新醅白，断绮重寻旧谱声。","匡济老臣心未减，却从江国望神京。"]},{"t":"题石城秋晚图送人归金华","f":"七言古诗","c":["金华才子天京客，登眺京城壮心魄。","钟岳群峰紫翠开，巴江一道东南拆。","石头艇子泛中流，白纻清歌起莫愁。","双阙五云笼建业，三槐万树接扬州。","烟景清清何绵邈，对面枫林更萧索。","月落乌啼北固城，潮生鹤唳丹阳郭。","怀亲作赋已堪怜，更托新图与代传。","琼佩暂辞丹毂下，斑衣归舞鲤庭前。","远归去去毗陵道，归日还应及冬早。","冰下寒鱼暂可叉，霜馀槲叶行堪扫。","天官若奏选材臣，应念词林卓荦人。","君往承颜多暇日，看花重入帝城春。"]},{"t":"西塘图为姑苏吴隐君题","f":"七言古诗","c":["放臣海曲怀京华，孤旅天涯念乡国。","谁传此意入图画，令我一见三叹息。","毗陵野老吴中人，旧与季子曾相亲。","太湖三万六千顷，荡漾咫尺阊门云。","姑苏台荒烟树绿，下着诗翁数椽屋。","凉风洲渚芙蓉开，细雨林园木瓜熟。","画船挝鼓海天晴，越女新裁白纻轻。","馆娃宫暗暮云合，子夜歌阑春水生。","季家风雅谁与比，况是吴兴外孙子。","曲几时摊旧赐书，牙签满插前朝史。","南来无复少年狂，茅栋低低一炷香。","久嫌尘居隘容膝，更置别业开西塘。","西塘隐约湖山曲，塘边还种虎邱竹。","对酒菰蒲照座明，捲帘鸥鹭当窗浴。","此图风致真可人，点染直欲穷天真。","平子愁来独长咏，张衡老去谁为邻。","吾观季子好风骨，正好还家及秋律。","笔床茶灶逐天随，莼菜鲈鱼莫相失。"]},{"t":"题黄万户德清罗浮图","f":"七言古诗","c":["将军昔年在东都，虎头铁面专城居。","重营柳暗流苏帐，左掖花明金虎符。","东都郊外多林壑，将军公馀事行乐。","露冕旌幢隘北山，行厨宾从如东洛。","紫云白云千万峰，罗浮更在二云东。","古木千章排叠巘，飞泉百道泻晴虹。","仙家洞天三十几，罗浮夐在沧洲里。","紫极房栊倚日开，蕊珠楼观经天起。","餐霞道士不知年，夜礼星辰诵内篇。","龙种玉芝耕赤谷，鹤衔瑶草下青田。","将军此时事幽讨，追攀极欲凌穹昊。","扶桑缥缈徐福舟，辇路依稀汉陵道。","别来倏忽几冬春，京洛相逢车马尘。","石室琅函仙梦远，朱衣琼佩岁华新。","新图谁为将军模，点染犹能记绵邈。","雨过琪花定满坛，星沉宝气应连阁。","我与将军总可怜，远游经岁复经年。","罗浮清赏如堪载，同赋陶潜归去篇。"]},{"t":"送友自馀杭归富春","f":"七言古诗","c":["君住西湖已清楚，胡为更忆庄遵渚。","归舟昨日凌天风，湖水秋风似秋雨。","忆昔狂游载酒行，画船为屋花为城。","银筝度曲对豪客，纨扇题诗招小琼。","小琼云鬟十八许，自按红牙歌白纻。","歌罢流云咽大堤，舞回落月低南浦。","高阳酒徒散如云，君亦携书隐富春。","侠气未全消野兴，青蓑聊复谢尘氛。","富春世外真林壑，不比西湖近城郭。","杨柳当门春正深，珊瑚拂袖花初落。","英髦岂必老江滨，天上应须有故人。","重着羊裘趋凤阙，还将高卧动星文。"]},{"t":"代内赠别二首 其一","f":"古风","c":["君之去也青骊之驷不可追，妾之留也凌波之袜不可随。","仆夫仓黄戒往路，断柳错莫留残晖。","玉觞行酒和泪血，问君此去何时归。","何时归，乱心曲。","春风看尽长安花，莫道新人如美玉。"]},{"t":"代内赠别二首 其二","f":"楚辞体","c":["君不行兮夷犹，长风飒飒林木秋。","岁云暮矣白日晚，君之行也不可以久留。","山川悠悠靡终极，独立空闺长叹息。","临歧不得逐行踪，别后相思复何益。","水中摸月那得轮，镜中照影那得真。","百年长是远离别，魂梦相逢那得亲。"]},{"t":"寄罗都事友章","f":"七言古诗","c":["梁侯昔在东藩时，分符帅阃兼左司。","君为幕府贵宾客，咳唾一落成珠玑。","君年于我当父执，我才弱冠君六十。","惠然下作忘年交，令我夜梦生撝挹。","灵鳌峰在江水边，清赏几时同周旋。","题诗秋写凤林竹，载酒夜泛兰溪船。","兰溪溪水清如练，兴尽回船复开宴。","水底潜蛟听凤箫，波心皓月摇秋扇。","梁侯权势盛莫当，偏裨小校皆为郎。","惟君与我得礼貌，过者啧啧盈路旁。","别来风物何可道，华表青青但春草。","我骑羸马走西东，梁侯去矣君亦老。","人生本是风花枝，升沉聚散何足悲。","优游晚岁谢微禄，倘得从君林下期。"]},{"t":"送都大尹","f":"七言古诗","c":["使君家住馀杭曲，年少狂游事追逐。","苏公堤上夜浮舟，越王祠前朝击鞠。","馀杭山水绿葱茏，一片西湖照晚空。","桂棹影摇桃叶浪，菱歌声彻竹枝风。","高阳酒侣动盈席，使君丰仪偏白皙。","湖光山色静娟娟，秋月冰壶影相射。","折节年来学读书，褒衣章甫逐群儒。","已超艺苑时流上，复耻陈编章句拘。","年纪今年三十七，风流众中称第一。","有才作县宁久劳，铜章绿绶须暂屈。","石头艇子泛清秋，晓发金陵信下流。","已逐行云经北固，还随轻浪到瓜洲。","生来我亦悠悠客，邂逅论文心莫逆。","家住江南五千里，送君又过江之北。","秋风淅淅江水波，君行我留可奈何。","长亭日夕一壶酒，从此关山魂梦多。"]},{"t":"送虹县尹陈影明","f":"七言古诗","c":["甲寅三月春欲尽，我来洪州寻吏隐。","芳声令誉谁最多，太丘之孙陈大尹。","大尹昔是会稽人，文章破的推殊伦。","奉天门下拜天子，来作洪州司土臣。","文章固自不必道，为官作事仍更好。","闾里小民持牒来，抚摩直欲置怀抱。","洪州昔日盛繁华，大尹来时一百家。","稍辟丘墟攒井里，旋披荆棘树桑麻。","桑麻春深满地黑，更掠浮泥种牟麦。","接舍鸡鸣桃李场，生氂犬吠藩墙侧。","祭社枌榆箫鼓鸣，群农皆醉吏独醒。","群农有酒只自饮，相见不揖亦不迎。","官清事省无鞭扑，县治门前可罗雀。","种柳宁惭目老陶，栽花直欲强潘岳。","父老皆言大尹贤，愿留大尹更三年。","政成入觐不可住，百里盼望心悁悁。","单车就道虹亭曲，卧辙扳辕泪相续。","囊里时无刘宠钱，车旁肯挂时苗犊。","三年俸米鹤同餐，焦尾琴轻古锦寒。","萧然行李可一笑，赢得车中裀面宽。","芙蓉花开亦已谢，十月清霜被平野。","何因欲去更迟留，父老相看不相舍。","黄河近日涨淮流，车到淮阳当换舟。","送行父老在平地，蹙额先作风波愁。","跨淮浮桥有客路，我教儿男送君去。","便从淮右向琅琊，却望丹阳登北固。","北固青山连石城，城南之下是天京。","仙台浮云树万直，帝里旭日千花明。","看花骑马金陵道，金陵行行须及早。","知君富贵心淡然，功名得后亦良好。","宗伯金门奏美除，政须贤令立高衢。","天京到日知安稳，多寄洪州父老书。"]},{"t":"送翰林典籍张敏行之官西土","f":"七言古诗","c":["敦煌城下沙如雪，敦煌城头无六月。","关西劲卒筑防秋，捷书夜半飞龙楼。","九重下诏徵貔虎，推毂上将开都府。","黄旗卷日大军行，旄头化石夜有声。","敦煌迢迢五千里，十月即渡黄河水。","上将翩翩才且雄，平戎不数贰师功。","叱咤犹在轮台北，匹马已入渠黎国。","左校偏裨晚射雕，倚鞍醉索单于朝。","西山黑风吹堕瓦，霜角吹秋塞垣下。","太平今见远宣威，君往从戎几日归。","幕下文儒兼解武，词林从此耀关西。"]},{"t":"送崔振宗","f":"七言律诗","c":["入幕初抛宪郎粟，芙蓉照水摇红玉。","鹗书迢递吴山云，孤棹夷犹越江曲。","龙江二月千花繁，好客元戎开酒樽。","花前岸帻一回首，应识前朝丞相孙。"]},{"t":"捕鱼图","f":"七言古诗","c":["小孤洲前春水绿，泛湖小船如小屋。","白头渔父不解愁，往来捕鱼湖水头。","得鱼换米纳官税，妻孥衣食长优游。","大儿十三学网罟，小女七岁能摇橹。","江口赛神夜吹角，村边卖鱼朝打鼓。","雨来维梢依古岸，风起鸣榔入长浦。","荻芽短短桃花飞，鳜鱼上水鲥鱼肥。","脍鱼烧笋醉明月，蛮歌唱和声咿咿。","月明在天光在水，但愿年年只如此。","无风无浪安稳眠，湖中有鱼鱼得钱。"]},{"t":"过隋宫故址","f":"七言古诗","c":["伊昔隋家全盛年，周陈部曲按三边。","端门彻夜笙歌合，琪树经春锦绣缠。","经春锦绣何摇漾，别有迷楼九霄上。","连拱飞甍次第开，朱帘绣柱森相向。","楼中美女花葱茏，写翠图黄映晓空。","璧月琼花新态度，临风结绮旧丰容。","碧山萤火光于电，更傍沉香山底宴。","窈窕清歌来梦儿，轻盈妙舞莲花旋。","行乐还来烂熳游，天京移跸望扬州。","高起离宫连凤阙，斜穿汴水入龙舟。","龙舟锦缆映牙樯，玉箫金管切云长。","仙禽自蜕葳蕤羽，野鸟还为鸾凤翔。","棹歌杨柳春风晚，扇影芙蓉秋露香。","芙蓉秋露香飘玉，台榭俄成走麋鹿。","翠华梦断雷塘路，铁马声喧太行麓。","辽东浪死鬼啼道，马上夜游谁度曲。","燕泥时自落空梁，庭草无人随意绿。","繁华堪羡复堪怜，高冢麒麟若个边。","古路斜阳悬木末，寒鸦流水绕村前。","荒基远对唐陵树，断碣犹存大业年。","往事悠悠谁与共，临风为尔一潸然。"]},{"t":"题堵法曹文明所画匡庐图","f":"七言古诗","c":["墨樵诗翁发垂耳，少年嗜画今老矣。","山鸡野鹿是前身，每见青山乐忘死。","高堂醉扫匡庐巅，香炉缥缈生紫烟。","我来一见似相识，仿佛偃卧彭郎船。","小孤鱼肥春酒好，何当举白醉五老，芙蓉倒影月出早。","与君同上乐天亭，令人夜唤琵琶听。"]},{"t":"次李阳河","f":"七言古诗","c":["橹声咿轧如人语，鱼吹浪花作飞雨。","停船把酒小孤山，顷刻回梢失前侣。","危樯五两飞向东，李阳河水起西风。","江豚翻波出复没，舟人倚柁认晴虹。","秋云阴阴树叶脱，树头黄睢犹聒聒，明日云开楚天豁。"]},{"t":"阻风雷港","f":"七言古诗","c":["秋霜夜落南港沙，丹枫柿叶如春花。","江豚风应九月节，浦口猎猎吹蒹葭。","柁公移船出沙尾，蒲帆逆风不得使。","斗鸣双橹助咿哑，雁应中流水声起。","白头浪里龙气腥，三日不到舒州城。","拢船把酒酹河伯，为问澒涌何当平。","九华山色长自好，行人一见一回老。"]},{"t":"武昌别鲁侍仪舍人文浚","f":"古风","c":["啧啧复啧啧，人生交契真罕得。","我居翰苑君仪曹，几载相闻不相识。","君名早已播南衢，出入金门早奏书。","不谓同乘建业水，还来共食武昌鱼。","武昌鱼肥春酒好，竟日流连得倾倒。","黄鹤楼头叶乱飞，金沙洲上秋将老。","狂歌浪谑清致同，看君更有古人风。","才如关西杨伯起，性似城东陈孟公。","相亲未几还分手，可怜新知乐未久。","君随征雁入巴陵，我挂云帆溯川口。","归期去去各凄然，今夕星河各一天。","秋晚还期来促膝，与君同赋远游篇。"]},{"t":"过瞿塘","f":"七言古诗","c":["我本江湖远游子，扁舟远过瞿塘水。","瞿塘八月秋风生，天上猿声落篷底。","鬼门关黑路险幽，我行短发寒飕飕。","洪涛摇山角井裂，怪石触雪鼋鼍愁。","冥搜欲极造化窟，飒爽始可清毛骨。","朝冲神女弄珠宫，夜瞰鲛人织绡室。","人生哀乐本无端，历此百折生凄酸。","桡翻健翅疾于鸟，那敢此地长盘桓。","离家江月今三皎，归棹乘流须及早。","布帆明日挂回飙，晴滩水落漩涡小。"]},{"t":"赠成都画者徐文珍","f":"七言古诗","c":["徐郎萧散云月姿，早年读易仍工诗。","金门献赋发种种，天随艇子天之涯。","黄牛白马瞿塘峡，雨雪萧骚鬓毛飒。","冯虚历览更穷搜，眼如饥鹰冻不匝。","朅来调笑诸侯门，锦城住屋如住村。","撑肠拄腹何所有，银河百折千昆仑。","酒狂兴发一挥扫，渺漭云烟塞晴昊。","黯入虚无鬼魅怜，光奔霹雳神蛟倒。","烟收云散江海空，峰峦错出金芙蓉。","恍疑八月十五夜，一叶著我潇湘中。","徐郎善画世稀有，同时谁复称妙手。","豪家屏幛林壑间，见者嗟吁不容口。","我谓徐郎莫自轻，便须濯笔写蓬瀛。","图成弱水三万里，与尔翱翔归玉京。"]},{"t":"盐井","f":"七言古诗","c":["寒泓石底莓苔冷，百尺长梯挂残绠。","荒山寂寂无飞烟，父老相传古盐井。","瀼东瀼西十万家，煮盐射利为生涯。","筠筒直下汲清泚，出釜灿白如霜花。","太平幸睹烽火息，十万今无二三百。","官封此井不敢开，岁岁渝洲买盐食。"]},{"t":"桂岩题王昌泰卷","f":"七言古诗","c":["桂树丛生山之坰，岩石磊落枝交撑。","隐如虬龙出沧溟，玄云盘盘团紫清。","源湫石底金飙生，天香纷飘浩盈盈。","广寒落阴湛空明，五岳印影清岩亭。","珠光粼粼摇洞庭，美女倒蹑黄鹤翎。","玉箫吹秋入冥冥，嫦娥酌以玻璃觥。","飞廉列缺撼不醒，归来沧洲呼祢衡。","记余天游神所经，仙家篆作山中铭。"]},{"t":"题四川都府照磨陈庭学小兰雪轩","f":"七言古诗","c":["鲜桃郁李烘锦城，白雪幽兰冷空谷。","喧哗绮靡人所羡，君独胡为爱清馥。","君方少年富文采，早入西清掌书牍。","天官宗伯司铨衡，更佐边神镇巴蜀。","开府同专三品印，退食初架三椽屋。","既营楚畹栽碧丛，复对天花咏黄竹。","春还国香始吐颖，飞霰尚集风轩曲。","丹蕤著粉馀嫩红，剑叶堆琼隐新绿。","一时芳致正称妙，更与千载相追逐。","鲁连节操高摩云，太白丰姿瑩如玉。","玉堂学士今太史，壮以词翰盈篇轴。","龙鳞篆籀争雪鲜，金薤文章共兰馥。","我亦能吟君好事，好买溪藤数千幅。","联篇写作清风图，长使虹光贯岩麓。"]},{"t":"题绵州同知曾傃古雪卷","f":"古风","c":["开风轩，望古雪。","琼崖瑶嶂千万寻，琪树珠林互明灭。","此雪千年亦不消，寒光濑彩长岧峣。","火云六月烁金石，滕六万片天花飘。","曾侯仙中人，胸次同皎洁。","公馀对雪开风轩，岩壑窗扉两奇绝。","高寒上与元气通，冰光百道飞白虹。","群真缥缈下遥夕，高驾缟车乘玉龙。","我昨神游共清赏，羽服翛翛恣长往。","浩水花明载酒船，天池月照披风氅。","蛾眉苍翠接仙台，缥缈坡翁跨鹤来。","桃花犬吠空斋里，黄竹柴门君自开。"]},{"t":"题张侍仪贞白独冷轩","f":"七言古诗","c":["留侯之孙琼玉相，翛然夐立洞八荒。","颜如梅花开晓芳，曲眉烟霏婉清扬。","朗吟碧空古洞章，飘风流铃韵何长。","璧月瑩瑩夜未央，天坛万籁鸣清商。","归来人间寄徜徉，寒山冱谷开云房。","层冰嵯峨照座光，虬龙松桧交青苍。","飞廉怒号滕六狂，舞霰不作天花香。","四檐银竹声琳琅，山鬼独宿神蛇藏。","渔童樵竖冻欲僵，先生兀然方坐忘。","虚室生白萃吉祥，金魅不跃龙不骧。","华池神水淡汪汪，开元丹田内炜煌。","幽斋无人隙轩窗，云封茶灶笼笔床。","故人山阴回酒航，老鹤赤壁愁横江。","神游清都朝帝乡，珍珠为楼玉为堂。","群真环佩参翱翔，皆骑素麒白凤凰。","尘中六月川气黄，我行汗雨如迸浆。","桂舟无楫川无梁，安得送我置汝旁。","衣之织女青霓裳，酌以西母玻璃觞。","顿令烦歊化清凉，毛骨爽飒三千霜。"]},{"t":"题叶夷仲瞻云轩","f":"七言古诗","c":["天台之山天尺咫，叶侯家住天台里。","侯家兄弟联班行，总以才名佐天子。","大侯作县多政声，小侯差小亦作丞。","乡人聚首作密语，阿堵名门生宁馨。","名门宁馨相济楚，大侯好文兼好武。","小侯词赋亦惊人，五言七言追乐府。","天台本与仙家邻，二侯亦是仙中人。","芝兰玉树晓辉映，桃花流水春氤氲。","十年分散游梁楚，匆匆高堂日将暮。","大侯去家已可怜，小侯在官心更苦。","日想严亲鬓已霜，二儿有泪如迸浆。","凌风欲借双黄鹄，千里送儿还故乡。","乡中何物令侬羡，云去云来千万片。","云来桑梓杳莫分，云去乡关隐还见。","岂无杨子屋三椽，亦有苏秦二顷田。","同居贫贱心亦乐，富贵远别徒悁悁。","三椽足以庇风雨，二顷宁当代禾黍。","宦游经岁复经年，胡不遄归奈何许。","丹阳水通东浙河，侬今欲度水无波。","石头艇子无钱买，云去云来奈尔何。"]},{"t":"题唐侍仪双鲤轩","f":"七言古诗","c":["唐生昔侍双亲时，当庭日舞如花衣。","严亲去世慈母在，孝养足慰无穷悲。","唐生今年三十几，慈母高堂尚多祉。","养志谁能论八珍，作堂暂寄名双鲤。","双鲤双鲤白且鲜，日须二斗新铜钱。","宁劳姜妇水中觅，不学王生冰上眠。","人生有亲殊可乐，亲馔有鱼尤不恶。","娱乐从兹到白头，声名况是登黄阁。","我生我生缠百忧，庭帏风木悲清秋。","为君援笔赋双鲤，每一读时清涕流。"]},{"t":"题孙典伏可居轩","f":"古风","c":["吾宗孙子云鹤仙，荷衣蕙带神飘然。","朝吟屈子远游赋，夜诵庄生秋水篇。","五湖风月穷清赏，青雀为舻桂为舫。","二女祠前听凤箫，小孤舟北闻渔榜。","归来匹马逐嫖姚，环佩锵锵近九霄。","承恩日侍金銮殿，卜筑还依朱雀桥。","桥头流水清如玉，杨柳青青映书屋。","照座虽无鄂渚花，当庭亦种沅湘竹。","沅湘竹色报春迟，文玉疏疏只数枝。","客去每凭诗作伴，朝回偏与静相宜。","卜筑不雕亦不画，厅事门前仅旋马。","高题汉篆名可居，君作其中可居者。","人生出处本无端，坎止流行信可安。","君不见长安甲第连云起，赢得人间图画里。"]},{"t":"题荆徵士茂之藏杨补之梅花图","f":"七言古诗","c":["老荆好梅如好色，嘉树宁论万金直。","屡乘泛雪王子舟，长蹑登山谢公屐。","万壑千林秋叶乾，飞鸿堕影报新寒。","塞北偏令百草折，江南还得一花看。","此花看处真奇绝，豹脚蛇鳞缀香雪。","楚女轻盈练素裙，湘娥冷澹胭脂血。","破寒疏瘦未宜人，照波临水韵如真。","却月观前新态度，灵风台下旧精神。","梅花万树先春发，老荆此时情欲绝。","烂醉宁辞水部狂，清吟拟补离骚缺。","归来白发老京华，无复孤山兴趣佳。","冻蕊枯枝谁更羡，夭桃郁李世争誇。","画图忽睹阳和面，老荆手段却轻旋。","仿佛瑶池月下逢，依稀庾岭云中见。","无情有恨独迟迟，世外丰容只自知。","黄阁由来皆贵眼，杨郎老去负明时。","开图见花被花恼，有图无花图亦好。","月落参横柰尔何，江空岁晏令人老。","老荆老荆吾所怜，九还诠诀会当传。","芙蓉宝鼎丹砂熟，去作罗浮峰顶仙。"]},{"t":"题苏明远画竹图","f":"七言古诗","c":["苏郎画竹如写帖，珊瑚为枝篆籀叶。","寒梢不及三尺长，远势直与青冥接。","青冥不辨西与东，云光竹色俱空濛。","飞廉排山振鸑鷟，霹雳迸火惊蛟龙。","奇搜不独竹色老，此旁有石仍更好。","想其落笔当酒酣，人间屏幛愁绝倒。","近时吴兴赵子昂，最能写竹穷青苍。","苏郎晚出继芳躅，湖海二妙相辉光。","十年不到潇湘浦，环佩空怀玉箫女。","相期共泛书画船，浓墨凄迷扫烟雨。"]},{"t":"题杨肇初墨菊图","f":"七言古诗","c":["苏郎墨菊真有香，老墨落纸生秋霜。","宛然著我三径底，日与野老同徜徉。","生平爱画仍爱菊，令人见此二美足。","犹疑已是重阳过，寒花疏叶心簇簇。","忆昨苏郎画菊时，君家数本方离披。","谁云清致不兼得，更对浊酒开东篱。","明朝酒醒宾客去，君独沉吟空绕树。","绕树还看墨菊图，君家此乐陶家无。"]},{"t":"题袁清溪所藏雪夜泛舟图","f":"七言古诗","c":["钱颙画山工画雪，山下寒江更奇绝。","万壑千林鸟倦飞，苍松古柏冻欲折。","清人何日纵冶游，银涛渺渺着孤舟。","黄罂碧杓置篷底，定是山阴王子猷。","故人高居剡溪曲，窄窄柴门锁黄竹。","遥怜孤鹤怨空山，尘榻无人伴幽独。","披蓑童头缩猬毛，龙鳞冰片难容篙。","凌竞历览有何好，博得老眼如馋猫。","冲寒乘兴莫匆促，回船拢岸也不俗。","故人开轩扫茅屋。","品字床头抗酒壶，留连坐到东方旭。"]},{"t":"题廉徵士梦雪舟","f":"七言古诗","c":["廉生心性如野鸥，前生恐是王子猷。","城居一载困炎热，夜梦泛雪乘扁舟。","扁舟一叶凌寒水，更著壶觞箬篷底。","鼓枻疑过柳港边，乘潮似出沙洲嘴。","月华雪色冰玉同，粼粼万顷涵晴空。","虚明上接元气白，皓彩直与银河通。","故人山阴无茅屋，何处重寻剡溪曲。","惟应赤壁鸣皋仙，夜半横江慰幽独。"]},{"t":"题陈隐君菊庄卷后","f":"七言古诗","c":["隐君种豆南山陲，清晨荷锄薄暮归。","馀閒更学树丛菊，茅屋前头花作围。","此花不比桃与李，万木凋零方吐蕊。","耀日黄金浅浅红，凌霜白玉深深紫。","孤芳似与九九期，落英不落长满枝。","嫣然羞作儿女艳，高洁独抱幽人姿。","此时隐君徐步屧，晨光熹微风猎猎。","晚圃寒花语断虫，东篱冷露留残蝶。","洛阳金谷盛繁华，江渚芙蓉照馆娃。","歌台舞榭岂不好，淡烟芳草令人嗟。","岁华将暮衡门里，寄傲羲皇时隐几。","见月开笼放白鹇，穿林采药寻黄绮。","平生嗜酒仍嗜书，诗比渊明差未如。","还开三径望俦侣，亦有五柳临庭除。","素琴抚弦惟袖手，葛巾且漉柴桑酒。","莫劳更赋归去来，惹得声名满人口。"]},{"t":"题唐仙方伎图布政徐本所藏","f":"七言古诗","c":["九重春色浮金辇，柳亸雕檐昼阴转。","阁门无事简书稀，朝下三郎幸南苑。","仗底微风拂赭黄，熏炉别殿送天香。","昭容婉娈翠娥黛，内史委蛇宫锦囊。","飘飘野老来何许，赐坐从容陪宴语。","卦气初生石鼎丹，清风自是蓬壶侣。","奚童忽启文书箱，白骡随地走如羊。","金华不识紫烟客，那得化石初平方。","骊山未起朝元阁，谁遣御前方伎作。","招邀青鸟天际来，勾引霓裳月中落。","渔阳铁骑战尘生，云栈萦纡路不平。","此时安得仙翁术，化作潼关百万兵。"]},{"t":"题桃源图","f":"七言古诗","c":["我昔城居困尘土，十年不到青山坞。","扁舟夜梦泛沧浪，鼓枻扬舲逐渔父。","江岸沿洄落日低，寻源直上武陵溪。","逶迤绿水春将晚，烂熳桃花路欲迷。","欲迷忽得青山口，仿佛微香露林薮。","溪流已尽复潜通，石洞斜穿不知久。","地廓川平景旷然，还疑别是一重天。","迢遥山径莓苔雨，缥缈人间桑柘烟。","遥观但见攒林木，近入茅茨始成簇。","居人不改故衣冠，井里犹存旧风俗。","风俗依依世上人，皆言来此避强秦。","初期暂隐还乡邑，遂尔高居隔世尘。","儿孙长大供衣食，男事耕耘女蚕绩。","春至桑麻雨露深，岁寒松柏星霜易。","东皋北陇恣锄犁，戴胜飞飞布谷啼。","傍舍雨晴云外牧，饷田日晏草中归。","归来路暗山光灭，妇女缫车声未歇。","舴艋仍教稚子撑，渔罾更换溪童结。","往来墟落只逍遥，无复州司下叫嚣。","社日冬旬会村曲，黄鸡白酒话渔樵。","渔樵不识人间世，雨笠烟蓑但容裔。","涧水冰融觉候和，庭柯叶落知风厉。","问我何为作此来，仙凡迥隔两悠哉。","园里青蔬为君摘，瓦盆薄酒为君开。","东邻西舍争来聚，相邀具酒犹炊黍。","旋除新竹敞南轩，更扫落花开别墅。","初闻嬴氏好纷奢，不谓山河属汉家。","金雀重来飞灌木，铜驼还去卧烟沙。","铜驼金雀何时已，年代不知今半是。","世上纷纭日渐过，山中岁月谁能纪。","棹开酒醒怅蘧蘧，却向山家对画图。","物外烟霞犹仿佛，空中楼阁已模糊。","模糊仿佛何由辨，只似当时眼中见。","鹤唳松梢露气消，鸡鸣树杪晨光炫。","临风抚卷独踟蹰，欲寄桃源父老书。","涧户岩扉应未合，笔床茶灶近何如。","桃源桃源休莫莫，未必山林秽城郭。","车书四海今混同，来享人间太平乐。"]},{"t":"雨中寄友","f":"五言律诗","c":["客有还家梦，空山雨正来。","寒生衣袖薄，风急树云开。","掩户坐终日，思君重几回。","琴边有清兴，能复醉深杯。"]},{"t":"山中写怀","f":"五言律诗","c":["野馆愁俱寂，空林日未斜。","看云偏忆母，为客久辞家。","独自嗟萍梗，非关恋物华。","晚来山雨里，犹见杜鹃花。"]},{"t":"光孝寺","f":"五言律诗","c":["雨叶菩提树，天花薝卜林。","尘机方外息，幽趣静中深。","野色连香积，秋声杂梵音。","随缘僧供里，余亦长禅心。"]},{"t":"酬王道原","f":"五言律诗","c":["凤池鸳鹭侣，几载此南迁。","柳色迎征棹，薇香忆盛年。","讼庭栽白蜡，官路到红船。","我亦金门客，逢君倍黯然。"]},{"t":"过东阿怀雪篷","f":"五言律诗","c":["故人今不见，孤客倩谁怜。","事业清时困，名声旧邑传。","紫髯风猎猎，纱帽月娟娟。","倘遂幽园约，琴樽共晚年。"]},{"t":"荔湾渔隐","f":"五言律诗","c":["家住半塘曲，沿回几折湾。","门前荔枝熟，屋后钓舟闲。","杳邈熊罢兆，空濛虎豹关。","如何三里外，便是五湖间。"]},{"t":"翠筠轩为源上座题","f":"五言古诗","c":["篁竹本修修，僧房分外幽。","祇园栽未合，因地养初稠。","苦节头陀行，虚心般若舟。","禅馀金粉落，定起箨龙抽。","渭叶慈云护，湘枝法雨流。","斜穿瘗雁塔，高过讲经楼。","色映菩提静，阴连薝卜浮。","军持浇记日，山偈刻知秋。","挂衲疏萤入，煎茶病鹤愁。","个繁教略洗，篱缺更须求。","腊纪应同祖，清缘或共修。","移床看翠葆，斫汗试银钩。","玉版供香积，渔竿拂石头。","风幡摇琐碎，月磬和萧飕。","阅岁开荒径，寻盟到野鸥。","闲门邀蒋诩，精舍候王猷。","石上摊棋局，林边列酒瓯。","素琴调白雪，彩笔画沧洲。","兴与梅花共，心同造物游。","更须三内翰，飞锡问扬州。"]},{"t":"朝云","f":"五言古诗","c":["思断兰台路，愁填濯锦川。","钱塘清楚会，金谷狭斜联。","少负倾城誉，名居弄玉先。","十三工写月，二八擅韶年。","束素官腰怯，凝脂国色鲜。","倚风杨柳弱，炙日海棠嫣。","跳脱松龙腕，琵琶重妥肩。","涂黄匀汉靥，安雁破秦铅。","绿水酣潘岳，红颜恼董贤。","流霞红错落，娇燕掠鞦韆。","舞压梨园社，歌翻乐府编。","彩云生袖底，璧月堕楼前。","镜掩三星曙，春随五马鞯。","青楼辞女伴，琼佩挹诗仙。","蜡炬催传赐，乌孙待草玄。","娉婷惊世外，风度盖吟边。","霜扑罘罳画，阴横粉署砖。","逆鳞天咫尺，垂翅路三千。","黛减蛾眉翠，筝斜蜀国弦。","武林牵北望，庾岭入南迁。","白鹤峰千尺，黄茅屋数椽。","练裙参般若，彤管拓张颠。","蜜鲫调苏合，边炉瀹海膻。","断霞丹荔屿，晴雪素馨田。","妾命真成薄，郎行底未旋。","尘蒙缨络串，珠亸步摇钿。","往事肠堪折，殊方瘴莫痊。","娃童占吉卜，邻媪访沉绵。","楚峡深秋气，罗浮澹晓妍。","巫阳招古些，下女泣新阡。","海气笼翘凤，岚光湿鬓蝉。","封囊留粉恨，长帽断尘缘。","陇树含栖绿，经文带泪镌。","雪儿低鹤驭，云母冻龙涎。","桃叶僧前渡，梅花梦里天。","蛾旋三昧火，鹦吊六如禅。","入道应偷药，凌虚想步莲。","浴兰依静土，遗玦赠灵荃。","天路云和悄，瑶池脉望圆。","回鸾珠斗没，惊鹊玉绳偏。","木落山精笑，苔平石兽眠。","香魂啼子夜，慧魄闷重泉。","络纬停寒索，飞帘卷夕旃。","谱馀苏小曲，书暗薛涛笺。","乱绪纷团结，新知永弃捐。","屏帏空孔雀，衿绣冷文鸳。","清吹群真下，丛林积水连。","幽扃萤扰扰，旧业草芊芊。","巴舞陈椒醑，吴歈裂楮钱。","霓裳飘蜀雨，斑竹点湘烟。","暮雨从渠湿，春冰敢自坚。","缟衣迷故国，华表竖层巅。","白纻行人唱，银釭傍舍悬。","芙蓉羞烂熳，蛱蝶舞联翩。","绣壤遮王嫱，勾栏倾阿甄。","红颜多蹇劣，清涕莫潺湲。","在世谁非幻，钟情我独怜。","微生同坎壈，幽思久婵媛。","禁闼初通籍，儒林早备员。","词华翚五凤，帏幄饫三鳣。","眉目端如画，丰姿美且鬈。","銮坡披奏牍，驰道鞚飞駩。","雅誉倾时辈，清流冠吏铨。","宾筵陪有客，羽猎赋于畋。","绮席延枚叟，蒲车屈郑虔。","天颜却下顾，云路快高骞。","昔似冲霄鹤，今如跕水鸢。","九关严虎豹，平路落鹰鹯。","拜命沾三宥，归耕困一廛。","壮心徒激烈，长袖几翩翾。","倦泛张骞梗，虚弯李广弦。","古苔封片石，荒枥卧双騝。","草茇临丹壑，柴扉枕碧涟。","奚童开雀网，稚子缚鱼筌。","白雪潘郎鬓，青灯子敬毡。","哀筝开缘蚁，雄剑搏乌犍。","雨露从枯槁，山林且静便。","朝真探玉诀，观妙解名诠。","丹鼎团龙虎，元龟卜涧瀍。","屋头杉隐隐，庭下竹涓涓。","薜荔裁秋服，枫香当晚饘。","关元存太乙，文火养纯乾。","七夕邀金母，三山候偓佺。","醴泉清似玉，瓜枣大如拳。","老去浑无赖，忧来独惘然。","有怀通尺素，何计索莛篿。","孤况凭谁问，冲襟待子宣。","莲飘知薏苦，藕断识丝缠。","惨澹黄姑渚，玲珑织女躔。","交疏期屡爽，谋拙去何遄。","画饼文章贵，婴儿造化权。","宁劳褰短褐，端合掩真诠。","病骨相如在，劳心宋玉传。","韩凭春寂寂，杜宇月娟娟。","邂逅时将晚，淹留景莫延。","流星光晻霭，雄电动连蜷。","艳态千秋隔，羁肠百虑煎。","锦蕤空薄暝，绛节映重渊。","洛浦凌波袜，西湖罨画船。","佳人不可见，长诵法华篇。"]},{"t":"琪琳夜宿联句一百韵","f":"五言古诗","c":["紫府黄金榜，玄关白玉京。","偶寻方外侣，因识静中情。","夕景低崇阙，秋光澹列甍。","宛闻天籁杳，浑觉世尘清。","缥缈群真下，森罗万象呈。","勾陈联上界，析木近前荣。","竹炫湘川叶，荃扬楚畹英。","幡幢行道影，环佩步虚声。","桂露蟾光湿，松涛鹤梦惊。","古囊缄绿绮，阴壁倚苍精。","净几从容凭，佳篇取次赓。","奚童髽发秀，仙客氅衣轻。","顿使心期旷，从知境界宏。","堂因众妙扁，轩以得閒名。","宴坐咸嘉会，兴言忆旧盟。","丰姿初得睹，怀抱即相倾。","友谊芝兰契，文声铁石铮。","乡关虽异县，年齿幸同庚。","才迈谁能匹，情亲我所兄。","长游期楚蜀，任侠拟幽并。","雅结南园社，狂为北郭行。","山风红叱拨，野日锦繁缨。","博带皆时彦，高筵即上卿。","柳塘晴睡鸭，杏圃暖啼莺。","南内霓裳曲，梁州雁柱筝。","风流追谢脁，俊逸到阴铿。","刻烛催长句，飞筹促巨觥。","欢娱随地有，意气抗霄峥。","乐事俄成梦，忧端忽谩生。","秦楼丝管歇，越峤鼓鼙兴。","培嵝封屯蚁，沧溟吼怒鲸。","孤城寻劫火，万姓转饥坑。","奔走羞徒步，艰危学避兵。","彭衙愁杜甫，战国老侯嬴。","袖贮生毛刺，家馀折脚铛。","娇婴须橡栗，邻妪遗蔓菁。","旧绣裁新褐，寒灯翳短檠。","苦心灰一寸，吟鬓雪千茎。","养志悲华黍，伤时赋代樱。","草玄供寂寞，居素保幽贞。","世态何多易，人情实饱更。","驽骀先历块，嫫母妒倾城。","康瓠迷周鼎，淫哇乱帝韺。","含沙丛毒蜮，触气捷飞虻。","默处忧心悄，傍观怒目瞠。","猛然思奋迅，郁尔困拘狞。","旅邸荣枯枕，秋棋黑白枰。","正怀三月吊，复有二天帡。","左相通书速，群僚倒屣迎。","剧谈劳过许，吾道赖遄亨。","楚楚红莲幕，团团翠柳营。","前茅瞻白羽，后劲拥玄旌。","尚想从军乐，深惭待士诚。","价酬千里骏，食共五侯鲭。","祖逖心何壮，陈琳伎善鸣。","闻鸡三尺动，倚马万言成。","勋业祇如此，行藏莫重评。","岛夷新版籍，烟雨旧柴扃。","凤历颁洪武，鸿图启大明。","包茅输禹贡，卉服奉周正。","黄道三台正，苍穹八柱擎。","文臣登稷契，武将拜韩彭。","恢拓神应助，提封孰敢争。","大荒空朔漠，平楚露搀抢。","闽土妖氛净，钟陵王气横。","隆恩光岳渎，至礼庆宗祊。","貔虎分环卫，蛟龙对拱楹。","河沉汉后璧，庙列吕公璜。","交阯来驯象，雕题进语莺。","堪舆欣有戴，师旅遂无征。","边翰开华省，名臣秉重衡。","远猷咨上士，深惠洽疲氓。","自念予生息，于今睹治平。","屠羊安返肆，买犊事归耕。","栗里山无数，桃源水一泓。","垦田先种秫，结屋便诛藑。","故作深林隔，还从曲港萦。","风萝猿叠叠，云木鸟嘤嘤。","径狭交平仲，洲回接杜蘅。","断崖攲削铁，悬瀑碎飞琼。","冉冉松吹粉，娟娟笋脱绷。","草寒愁格磔，沙霁喜鵁鶄。","鱼网樵青结，禾船稚子撑。","物情俱自得，吾意岂求赢。","药裹从堆案，书签或满棚。","绳床低窣兀，石鼎小彭脝。","隐具家粗足，闲工日计程。","梯岩探野蜜，堰水捣香粳。","紫斸蹲鸱芋，红收荐蟹橙。","缺篱添补竹，荒圃剩移柽。","陶令茅柴酒，东坡骨董羹。","任真形放浪，坐懒发鬅鬙。","更学丹砂诀，长离世网婴。","御风求抱朴，缩地候茅盈。","绮食青精饭，黄茅紫石瑛。","凌虚朝日表，观化睨天精。","蠢蠢哀群动，飘飘隘八纮。","瑶池传鸟信，缑岭度鸾笙。","弱水秋初浅，清都夜正晴。","寄言萧羽士，来此共蓬瀛。"]},{"t":"南山杂咏","f":"七言律诗","c":["湘潭千顷碧波澄，争似南山一段青。","山雨欲来云气重，江鸥飞去钓船轻。","诗成多是琴边兴，老去应怜物外情。","闲唤小童敲白石，不知芳草夜来生。"]},{"t":"峡山寺三首，其三与郑御史李逾国同登时再召赴阙 其一","f":"七言律诗","c":["峡束沧江万壑雷，梵王楼阁倚天开。","山从中宿城边去，水自连州港口来。","云叶卷时猿献果，雨花飞处客登台。","青鞋未访和光洞，奏赋金门亦壮哉。"]},{"t":"峡山寺三首，其三与郑御史李逾国同登时再召赴阙 其二","f":"七言律诗","c":["竹里维舟陟翠微，闲门临水欲嵚巇。","云生佛殿飞来处，猿啸山僧出定时。","断刻尚馀梁日记，古松犹偃汉朝枝。","烟霞二妙应相笑，盛世藏珍负夙期。"]},{"t":"峡山寺三首，其三与郑御史李逾国同登时再召赴阙 其三","f":"七言律诗","c":["明日青阳逼岁阑，绣衣聊得共跻攀。","云铺鹤背浮金殿，风引猿声怨玉环。","薄宦岂堪长作客，故乡惟有一登山。","绳床睡暖梅花月，输与蒲庵老衲闲。"]},{"t":"游罗浮三首 其一","f":"七言律诗","c":["白鹤峰头春暮时，水帘洞口苍庚飞。","千林锦树化红雨，百道玉虹穿翠微。","神朝帝阙鹤为骑，灵语仙坛霞作衣。","坐怜佳致恼魂梦，应觅真人扣息机。"]},{"t":"游罗浮三首 其三","f":"七言律诗","c":["四百峰峦拱御台，蕊珠楼阁倚云开。","荔枝花落山鸠语，卢橘子生江燕来。","黄野故居羊化石，葛洪丹灶锦为苔。","仙游傥遂凌风约，羽服黄冠亦快哉。"]},{"t":"拜祖墓","f":"七言律诗","c":["芳草凄凄夕照前，独将春酒酹荒阡。","已嗟世事成千古，才说清明又一年。","满目江山增旧恨，几家榆火起新烟。","从来俯仰伤怀抱，不似于今倍黯然。"]},{"t":"重过林氏别业","f":"七言律诗","c":["曾侍先君访大邱，葛巾投老尚封侯。","青筠帘卷风生席，白纻歌残月满舟。","兴发共吟鹦鹉赋，酒阑重解鹔鹴裘。","传家幸有贤孙子，别业新成似旧游。"]},{"t":"题海翁诗卷后","f":"七言律诗","c":["海屋珊瑚几度花，仙筹长为记年华。","天晴雾雨笼蛟室，夜冷星辰泊钓槎。","巢父诗篇留宇内，严陵名字达皇家。","无因一遂神游约，共觅安期枣似瓜。"]},{"t":"灵洲","f":"七言律诗","c":["金鳌露背出沧溟，撑拄惟应倩巨灵。","坡老留题空断偈，德云种柏满幽庭。","天寒怖鸽依江渚，夜静灵鼋听塔经。","画舫图书催入觐，庾梅关北树青青。"]},{"t":"景泰寺","f":"七言律诗","c":["何年鹫岭列群仙，寺外千峰紫翠鲜。","白露积山秋蔼蔼，苍松夹道涧涓涓。","三城雁翅斜连海，双塔龙光直到天。","此地登临送车骑，路人争说使君贤。"]},{"t":"赠黄观复先生","f":"七言律诗","c":["先生归业西南坞，白发重来避乱离。","流水桃花西晋梦，野云晴树盛唐诗。","秋池竹影浮书席，午灶茶烟飏鬓丝。","同抱遗经老林壑，顾惭何用副明时。"]},{"t":"元日","f":"七言律诗","c":["故国东南气候偏，频婆卢橘得春先。","每逢元日兼人日，共说今年胜去年。","汉苑秦台连锦绣，游丝落絮送秋千。","艰虞弟妹知谁在，为尔临风一怅然。"]},{"t":"送人之南京","f":"七言律诗","c":["知君迢递拜金銮，谁信西风送别难。","路入楚天千里外，心随明月五云端。","石门干落孤帆远，庾岭秋高白露寒。","翰苑若逢相识问，为言还着旧儒冠。"]},{"t":"秋江送别","f":"七言律诗","c":["千家城郭远依依，握手离筵话夕晖。","碧海云深秋自老，芦花风急雁初飞。","客情犹醉千钟酒，书剑谁怜万里归。","慈母白头应问信，倚门遥识老莱衣。"]},{"t":"送赵宣使之德庆","f":"七言律诗","c":["阿翁高步金鳌背，南郡今留彩凤雏。","名姓几年通上国，才华早岁入中书。","花明画省诗千首，木落寒滩酒一壶。","若到廉州烦借问，故人黄赵近何如。"]},{"t":"别王彦举","f":"七言律诗","c":["东风吹赴龙头选，又别王郎听雨轩。","既拥青绫吟北牖，更张红烛醉南园。","秋还芸草书香秘，夜久芙蓉漏滴繁。","后夜玉堂追往梦，一簪华发共谁言。"]},{"t":"送林毅寄彭万里参政","f":"七言律诗","c":["闻君作宦山西去，为我持书问故人。","青社部符藩屏重，黑头当轴宠光新。","中原几载无狼虎，大野清时识凤麟。","同侍禁闱今远别，鹧鸪啼杀上林春。"]},{"t":"乙丑元夕送傅城进士还桂林","f":"七言律诗","c":["旧时相见即相欢，见说如今又作官。","湖海别魂空窅窅，天涯愁思独漫漫。","春风几日来江上，灯火逢君坐夜阑。","忽报故园归思切，素琴惆怅不胜弹。"]},{"t":"到京","f":"七言律诗","c":["金阙瑶宫拥翠华，茫茫人海聚豪奢。","明廷礼乐超三代，盛世车书混一家。","龙虎山川昭胜概，衣冠文武际亨嘉。","粤南草莽臣欣睹，瑞日祥云护彩霞。"]},{"t":"钟山应制","f":"七言律诗","c":["苍翠巍峨插昊穹，紫金突起大江东。","三山避迹投鲸海，五岳齐肩拥帝宫。","珠树凤鸾鸣瑞日，宝圻龙虎壮威风。","万年圣寿高堪并，常有神人祝华嵩。"]},{"t":"新春从幸天界寺次詹冢宰钟山应制韵","f":"七言律诗","c":["天界丛林开象魏，朱衣环佩俨群仙。","瑞露迎銮飞扈跸，皇都佳气蔼新年。","玉宸香满三千界，莲座光浮尺五天。","敕使御前催应制，侍臣簪笔思如泉。"]},{"t":"驾游钟山应制","f":"七言律诗","c":["玉宸警跸出蓬莱，近望名山翠色开。","松柏屯云车骑过，峰峦簇锦节旄来。","九成奏乐喧泉涧，百职联班蹴蹬苔。","宴赏太平当赋咏，小臣侍从愧非才。"]},{"t":"驾幸天界寺和朱太史芾韵","f":"七言律诗","c":["宴语从容对上方，侍臣挥翰笔如扛。","从行卫士随僧供，出定经声歇梵腔。","鹫岭晓云扶辇毂，龙河春水漾旌幢。","清平自觉文章盛，长忆天兵未渡江。"]},{"t":"陪翰林宋承旨游钟山","f":"七言律诗","c":["天上禅关敞薜萝，每缘休沐得经过。","云笼梵宇青莲湿，地接皇居紫气多。","甘露结花凝木末，醴泉如雨落岩阿。","欲陪谢傅金屏约，未解朝簪奈尔何。"]},{"t":"朝奉天门","f":"七言律诗","c":["三陲寂静简书稀，不谓馀生睹盛时。","月窟天根周正朔，琼琚玉佩汉官仪。","蓬莱旧隐违仙赏，葵藿微衷结主知。","尚想临轩膺顾问，徘徊当宁退朝迟。"]},{"t":"贽左相宣国李公","f":"七言律诗","c":["吾皇神武定山河，上相奇勋盖世多。","周室兴王尊吕望，汉朝开国任萧何。","形图麟阁威当仰，铭勒燕然耿不磨。","胙土分茅延世赏，振振麟趾沐恩波。"]},{"t":"呈中书参政汪公","f":"七言律诗","c":["龙飞江左际风云，忠赤谋猷夙夜勤。","枫陛论思严国体，薇垣计策净烟氛。","褒贤奎画黄麻敕，补衮华虫色线文。","承荐鲰生何以报，只将俚语颂元勋。"]},{"t":"奉左司郎中顾光远","f":"七言律诗","c":["九天拜命带天香，南粤旬宣礼义乡。","青琐闼前恩渥重，紫薇垣里政声扬。","田畴万顷蟠秋黍，海国群黎贡栈航。","奕叶传家忠与孝，化为霖雨济遐方。"]},{"t":"诃林送赵生留南归","f":"七言律诗","c":["几年烟月共林坰，此日看花入帝城。","老我未酬清世念，别君因起故园情。","朝廷有道容樗散，献纳无才愧圣明。","归去为烦先问信，沧江渔艇白鸥盟。"]},{"t":"寄赵进士安中","f":"七言律诗","c":["词林每问归安使，闻说先生在德清。","暇日画帘公吏散，春风华馆子衿明。","三年不见新书札，百里空传旧政声。","日暮碧云何处合，思君吟遍石头城。"]},{"t":"送张典籍讷之官大同经历三首 其一","f":"七言律诗","c":["春风鸣玉下天阶，万里从戎亦快哉。","远仗皇威清朔漠，更依云气望蓬莱。","参军孙楚登瀛客，草檄陈琳补衮才。","边事太平烟火息，柳营羌角为谁哀。"]},{"t":"送张典籍讷之官大同经历三首 其二","f":"七言律诗","c":["边陲见说青烽灭，赞画遥知白羽闲。","夜月葡萄毡帐底，春风筚篥柳营间。","贾生长是怀金阙，定远安能老玉关。","沙漠年年飞羽捷，想随骠骑凯歌还。"]},{"t":"送张典籍讷之官大同经历三首 其三","f":"七言律诗","c":["文章堂上论交日，对榻哦诗白昼长。","晴日画帘观水影，暖风罗袂散天香。","寻常应制才堪并，四十从戎鬓未苍。","春半黄河冰片解，旌麾几日望敦煌。"]},{"t":"奉致仕詹天官","f":"七言律诗","c":["京华帝城春事幽，相君家住城南陬。","垂杨缺处水当户，燕子飞时花满楼。","宾客金鱼悬玉佩，儿孙锦带挂吴钩。","乡园父老傥相问，佐国元勋今白头。"]},{"t":"奉太史令护军公","f":"七言律诗","c":["虞渊捧日帝羽仪，文事武备天人师。","笔端词翰河汉决，胸次韬略风云随。","邦基肇造古伊吕，谟猷笃棐今皋夔。","画图麒麟盟带砺，仙游更与赤松期。"]},{"t":"投赠山东何方伯三首 其一","f":"七言律诗","c":["碧落初看王气清，丹山喜见凤凰鸣。","分符出镇留遗爱，赐第荣归荷圣情。","李绩忠贞明日月，窦融勋烈著丹青。","白头风度浑如昨，尚可登庸佐太平。"]},{"t":"投赠山东何方伯三首 其二","f":"七言律诗","c":["皇风来播南陲日，开府兼持将相权。","千里分封鸾诰下，三珠耀日虎符悬。","长怜野日违清愿，且喜恩光照暮年。","勋业已成头半白，蒋陵佳气丽中天。"]},{"t":"投赠山东何方伯三首 其三","f":"七言律诗","c":["君侯昔在东藩时，英风远略人共知。","帐前铁骑金锁甲，腰下宝玦珊瑚枝。","将相兼权未足贵，身名两存今始奇。","便可临风搔白首，对酒且赋归来词。"]},{"t":"送张翰林孟廉赴山西行军三首 其一","f":"七言律诗","c":["日陪珠履下瀛洲，奏对銮坡最上头。","校艺曾闻三献赋，从军喜遇一封侯。","辕门羽檄清秋静，奎府文光午夜浮。","顾问旧臣多特召，泥金会见出龙楼。"]},{"t":"送张翰林孟廉赴山西行军三首 其二","f":"七言律诗","c":["汉将防边意气豪，参军行处拥旌旄。","云连白雪飞花片，风卷黄沙似海涛。","塞曲但闻吹筚篥，人家多自种葡萄。","升平见说从戎乐，欲解儒衣问战袍。"]},{"t":"送张翰林孟廉赴山西行军三首 其三","f":"七言律诗","c":["清时况是金闺老，跃马关河鬓未华。","翠柳东门开祖帐，黄河北岸拥高牙。","安边羽檄传司马，落帽西风忆孟嘉。","万里封侯吾辈事，迟君谈笑靖胡沙。"]},{"t":"奉酬刘友贤黎仲辉二御史见过","f":"七言律诗","c":["故人骢马晓相过，错莫邻人避玉珂。","朝下楚城高盖合，春深门巷落花多。","飞腾每羡青云早，衰懒无如白发何。","相见惟期树勋业，蒋陵佳气正嵯峨。"]},{"t":"寄彭万里给事时参山西政","f":"七言律诗","c":["与君文彩旧同朝，翠管文章上九霄。","辇路香风随卤簿，天坛花雨听箫韶。","鹓鸾一别京关远，云月三年楚水遥。","欲寄清诗慰寥阒，汴河东去近无潮。"]},{"t":"送沈主事起复徐西安知县","f":"七言律诗","c":["年少天官旧考功，马蹄催入未央宫。","声名已在云霄上，乡国犹悬涕泪中。","辇路繁花明旭日，佳城乔木语天风。","传家正欲存忠孝，千古君臣此道同。"]},{"t":"寄郑御史毅","f":"七言律诗","c":["不见能诗老郑虔，七闽山色远依然。","桃花流水瀛洲客，兰叶春风御史船。","别后丰姿浑似玉，醉来毛骨欲成仙。","勋庸封拜多殊泽，归日应陪上相筵。"]},{"t":"寄张御史常泰","f":"七言律诗","c":["故人清楚旧能诗，去岁东南折桂枝。","久拟手容清百辟，故将文采应昌期。","诗题翠柏趋期早，颂奏嘉禾出殿迟。","寥落与君长见面，无烦千里寄相思。"]},{"t":"题黎仲辉御史先君墓志","f":"七言律诗","c":["广文振佩趋朝日，当宁临轩策士时。","黄阁侍臣催奏牍，玉堂学士诵清诗。","千花晓日文园合，一铎西风客棹迟。","遗老寂寥芳岁换，空山松柏雨丝丝。"]},{"t":"怀刘宪副子高","f":"七言律诗","c":["泥酒兵曹老职方，蒋陵花柳纵清狂。","雨晴振佩还西掖，日晏鸣镳出未央。","朝散锦袍香拂拂，吟成诗句玉琅琅。","燕台北去西风冷，谁伴吹箫引凤凰。"]},{"t":"寄罗友章先生","f":"七言律诗","c":["三年薄宦淹吴楚，长忆先生在海涯。","不著朱衣垂玉佩，还将白发映乌纱。","遥天剑气藏珠斗，百越文光绚彩霞。","云路相期苦相失，春莺啼彻上林花。"]},{"t":"圜丘大祀","f":"七言律诗","c":["松柏萧森倚半空，天坛高峙帝城东。","宸旒肃穆千官合，卤簿辉煌万国同。","上界清都移碧落，泰阶黄道隐晴虹。","相如莫献青鸾赋，不是祈灵太乙宫。"]},{"t":"寄黄员外文博时出佐守徐州","f":"七言律诗","c":["使君文学冠贤科，入拜工曹意气多。","五色云中披奏牍，九重天上振鸣珂。","趋朝共沐恩波阔，出守谁怜岁月过。","会有蒲轮徵故旧，未应黄发老蹉跎。"]},{"t":"怀王彦举三首 其一","f":"七言律诗","c":["怀昔南园王给事，同开诗社向沧洲。","凌风欲赴三山约，听雨还为十日留。","蚁绿新醅浮翠盎，茧黄旧纸试银钩。","别来风物应无恙，幸喜微官未白头。"]},{"t":"怀王彦举三首 其二","f":"七言律诗","c":["早岁南园开洛社，哦诗纵酒野云边。","元龙豪气三千丈，翰苑文章二十年。","春暖翠环歌白雪，夜阑银烛飏青烟。","幽期寂寞沧洲里，何日天风泛画船。"]},{"t":"怀王彦举三首 其三","f":"七言律诗","c":["闻道南园华物冷，小烟寒雨闭柴门。","频年久负沧洲趣，此日谁过杜曲村。","肯有文章千载重，不知朋旧几人存。","芳辰乐事成陈迹，江水江花酒一樽。"]},{"t":"怀黄徵士观复","f":"七言律诗","c":["积翠西南天柱峰，中天仿佛玉芙蓉。","时清有客歌鸣凤，地僻无人见卧龙。","白璧明珠淹下国，丹崖绿壑寄高踪。","匡时正有丘园念，几欲驰书道莫从。"]},{"t":"送刘芳之入蜀","f":"七言律诗","c":["峨眉西上穆陵关，犹似帘栊响佩环。","华月高秋沉楚馆，彩云清晓散巫山。","鸾衿寄恨今宵永，锦字传情几日还。","惆怅风前花落尽，相思惟有泪潸潸。"]},{"t":"饯宋承旨潜溪先生致仕归金华七首 其一","f":"七言律诗","c":["鳌峰朝日鹊声稀，内使传宣下紫微。","予告不须留秘阁，许归仍及赐春衣。","恩浓玉检天书湿，人去金茎瑞气稀。","况是阳和二三月，都门柳色正依依。"]},{"t":"饯宋承旨潜溪先生致仕归金华七首 其二","f":"七言律诗","c":["先生家住金华里，门对双溪绿水流。","烟树几年封故宅，云涛此日送归舟。","怀京想梦三呼祝，载酒还登八咏楼。","今夜寂寥清禁直，紫薇花上月如钩。"]},{"t":"饯宋承旨潜溪先生致仕归金华七首 其三","f":"七言律诗","c":["承恩初入词林日，亦得叨陪侍从班。","云影九重开凤阁，天光咫尺近龙颜。","彤闱侍读青春暖，彩笔题诗白日闲。","此去定酬优老愿，软轮游遍浙东山。"]},{"t":"饯宋承旨潜溪先生致仕归金华七首 其四","f":"七言律诗","c":["保傅储皇二十春，白头归去岁华新。","优贤宠渥非缘老，盖世文章不是贫。","锦诰焕颁云五色，青宫喜见日重轮。","悬知恋阙丹心在，长倚遥天望紫宸。"]},{"t":"饯宋承旨潜溪先生致仕归金华七首 其五","f":"七言律诗","c":["一自先生离禁闼，玉堂清致更无人。","金莲飏彩初寒夕，燕寝凝香散暮春。","著作有官惟故事，论思此道竟谁陈。","青云志气惭悲梗，不觉临岐泪满巾。"]},{"t":"饯宋承旨潜溪先生致仕归金华七首 其六","f":"七言律诗","c":["妙誉芳声照简编，丹青不待绘凌烟。","清朝礼乐词林出，史馆文章异域传。","贝锦春明天竺国，虹光夜贯日南船。","匡时已是吾儒事，赢得高参面壁禅。"]},{"t":"饯宋承旨潜溪先生致仕归金华七首 其七","f":"七言律诗","c":["龙门佳致接仙山，旧筑茅堂紫翠间。","方外羽人霞作袂，瀛洲归客玉为颜。","常时望气怀京国，午夜朝真响佩环。","愿祝圣朝千万寿，还随笙鹤到天关。"]},{"t":"诸王之国观礼有作","f":"七言律诗","c":["帝子承恩恋九重，应门下诏趣分封。","珠旒列拜宸居肃，玉佩随行礼数同。","祖训丹书皇有极，天人宝历世无穷。","君亲在望频回首，旌旆翩翻鸟隼风。"]},{"t":"怀刘文学中美","f":"七言律诗","c":["村居最忆龙津好，五月南风熟荔枝。","绿树千章云漠漠，明珠万解火离离。","风亭月榭孤人兴，楚水淮山恼梦思。","遥想故人招旧隐，几从猿鹤问归期。"]},{"t":"赠达禄修撰道夫","f":"七言律诗","c":["蓬鬓飘萧洛上翁，金门日日候晨钟。","论思入奏天光近，对御题诗烛影红。","衣故尚馀当日绣，马寒犹是旧时骢。","词华已作青云客，圣代于今雨露浓。"]},{"t":"西樵山","f":"七言律诗","c":["西樵山势捲飞龙，万里扶桑海色通。","日丽锦岩开罨昼，雨馀银渚漾芙蓉。","紫河车荫仙人掌，白鹤花明玉女峰。","上相朝元鸣玉佩，三城佳气郁葱茏。"]},{"t":"怀修撰朱备万","f":"七言古诗","c":["先生旧是瀛洲客，文藻风流第一人。","华月玉堂仙署冷，西风辽海鬓毛新。","文园最忆相如赋，茅屋谁怜杜老贫。","圣世云衢需俊彦，肯令漂泊暮江滨。","济济群贤圣度宽，怜君何事戴南冠。","清时文物为儒贵，晚岁关山行路难。","丹凤五门春日丽，玄菟万里海风寒。","蒲车早晚徵耆旧，莫作长沙谪宦看。"]},{"t":"冬至","f":"七言律诗","c":["冬至至日日初长，久客客怀怀故乡。","梅蕊惟愁雪烂熳，柳条又是春相将。","懒朝违世真自笑，忆远寄书殊未央。","海门关外暮云合，应有南还征雁翔。"]},{"t":"己未除夕","f":"七言律诗","c":["四十今已过二年，明日又复岁华迁。","头颅种种见白发，生计落落仍青毡。","梅花乱开客愁里，云物长迷乡国边。","且可吟诗酌春酒，烂熳取醉东风前。"]},{"t":"寄梁孟素","f":"七言律诗","c":["昔侍鳌峰先大夫，归山仍得佩金符。","楼船载酒春将半，花寺寻僧日向晡。","京国风云催步武，浙江烟雨送头颅。","音容久旷交情在，岁晚临风忆凤雏。"]},{"t":"赠端孝思文学","f":"七言律诗","c":["庆门昆季总能文，京国长随老使君。","休沐东山人似玉，退朝南陌骑如云。","金龟换酒犹能忆，玉树临风夐不群。","莫向炎门悲往事，词华已足继清芬。"]},{"t":"和翰林典籍牛士良使安南之作","f":"七言律诗","c":["五两招摇百尺杠，官舟十月下藤江。","波心犀气寒通剑，石角潮声夜扑窗。","酒荐吴盐浮腊味，歌传楚艳入巴腔。","扬舲我亦蓬莱客，应趁春风画桨双。"]},{"t":"宋伯祯处士东园","f":"七言律诗","c":["买得长镵斸翠苔，青茄白苋绕篱栽。","园翁作伴还成趣，野老赓诗只漫裁。","蛱蝶蜻蜓随上下，葛巾藜杖久徘徊。","临流学试羲之帖，会有函诗马上来。"]},{"t":"凤凰台","f":"七言律诗","c":["绮翮千年去已遥，古台犹见碧岧峣。","枫林晓雾迷三楚，柳陌春风暗六朝。","狂客昔时挥彩笔，飞仙何处撚琼箫。","惟馀一道巴江水，流向天门作海潮。"]},{"t":"再游钟山","f":"七言律诗","c":["空青楼阁□冥间，云是东南第一山。","武帝鸾旗烟草碧，志公龙锡雨花闲。","江光远荡鼋鼍窟，云气常笼虎豹关。","欲驾天风凌绝顶，上方琪树夕阳还。"]},{"t":"寄王主事希文之官漳州","f":"七言律诗","c":["湖海交游似晓星，南宫长史独多情。","清时吏散诗同赋，浊酒朝回日共倾。","金水桥边看浴马，紫薇花上听流莺。","岁华摇落人千里，何处漳州海上城。"]},{"t":"赠性空上人","f":"七言律诗","c":["一见清容类远公，六传清派出南宗。","已离世相诸方外，犹挂诗名万袖中。","龙钵夜珠留海月，虎台秋木啸山风。","天游不是长枯寂，舍利神光似火红。"]},{"t":"喜雨","f":"七言律诗","c":["崆峒云气远嶙峋，万片从龙下孟津。","三月久晴农事晚，一时甘雨帝城春。","蟠桃花发丹砂炫，御柳条长翡翠匀。","老我宦游归计阻，仙台几度药苗新。"]},{"t":"怀旧游寄李士行","f":"七言律诗","c":["忆上高台望赤霄，火轮光动彩虹飘。","鲛人夜织明珠佩，龙女晨参绛节朝。","迤北关山周正朔，平南将校汉嫖姚。","狂游又是三年别，海上蟠桃露气销。"]},{"t":"寄高彬","f":"七言律诗","c":["条风二月古隋堤，杨柳青青拂水齐。","万里客怀将白发，一年春信又黄鹂。","亲朋岁久愁多望，故国书成醉懒题。","惟有别君情不浅，梦中时到石城西。"]},{"t":"送蔡九节还南安","f":"七言律诗","c":["向年为客怕逢秋，每见春来忆旧游。","归梦夜随寒雨急，片帆飞逐大江流。","看山有兴还堪写，惜别从来不解愁。","斗酒殷勤拚一醉，相思何处却登楼。"]},{"t":"春兴寄端方故居","f":"七言律诗","c":["乱藤高竹散清烟，独倚阑干思渺然。","流水恨随春浦阔，故人家住白云边。","三年远别空相忆，一段新愁自可怜。","欲得山阴晴夜雪，东风吹放大江船。"]},{"t":"西岩图 为严彦恭题","f":"七言律诗","c":["欲写沧浪愧不才，画图今喜见君开。","峰峦影落寒潭静，欸乃声从返照来。","千顷白波龙伯国，百年高兴子陵台。","闻君早晚趋金阙，风雨渔矶长绿苔。"]},{"t":"送人还乡","f":"七言律诗","c":["岁晏那堪送独归，石门烟树晚依依。","几回客思愁江浦，十幅蒲帆挂夕晖。","沽酒乍闻何处笛，问程应为故山薇。","到时犹想多幽兴，一乐堂深见舞衣。"]},{"t":"怀白云山房","f":"七言律诗","c":["家住沧洲洲上山，数椽茅屋乱云间。","天晴叠嶂开金碧，雨过清泉响佩环。","高兴别来长寂寞，故人谁与共跻攀。","洞门猿鹤应相问，何事先生久未还。"]},{"t":"再寄罗友章先生","f":"七言律诗","c":["白发中林老散仙，别来长拟共周旋。","凤台僧舍秋题壁，兰石清溪夜扣舷。","渔唱晚霞红蔼蔼，醉吟夜月白娟娟。","无因一献长杨赋，辜负清游四五年。"]},{"t":"征南将军回京","f":"七言律诗","c":["统领貔貅净海隅，封狐狡兔总消除。","风雷自昔凭神算，巢橹从今息战车。","不学伏波私薏苡，得如武惠载图书。","勋阶冠着貂蝉贵，捷报常看锡帝居。"]},{"t":"怀海珠寺","f":"七言律诗","c":["海上蠙珠占一泓，分明梵宇住蓬瀛。","虹浮光彩生灵蚌，树拥楼台压巨鲸。","湘女佩遗存颗粒，商人帆过拂檐楹。","十年京国心南鹜，应负沙头白鸟盟。"]},{"t":"除夜","f":"七言律诗","c":["大地白雪似白沙，游子况复未归家。","寒云黯淡暗海曲，春风浩荡来天涯。","楚山卢橘渐舒叶，故园枇杷应着花。","未得乘船出江口，枯坐旅邸如春蛙。"]},{"t":"出京","f":"七言律诗","c":["水落轻舟搁浅沙，客心长是恋京华。","祥云晓护钟山树，旭日春明上苑花。","仙佩每闻催夹仗，宫壶曾记出流霞。","白头归去丹心在，茅屋三年梦帝家。"]},{"t":"之官平原留别诸老","f":"七言律诗","c":["朱衣和泪别龙庭，瘦马嘶风出凤城。","托迹禁闱原已重，之官名邑未全轻。","驰驱祇笑儒生拙，悯念难忘圣主情。","后夜玉堂清夜永，紫薇花月向谁明。"]},{"t":"别妓","f":"七言律诗","c":["骊驹西上帝皇州，斜抱云和泪暗流。","子夜歌词翻白雪，残春风物似清秋。","青鸾信断阳台路，翠被香寒燕子楼。","七十二泉萦别恨，济南烟树绿幽幽。"]},{"t":"代妓送别","f":"七言律诗","c":["清歌一曲转阳关，况是山城春景阑。","翠黛愁来空自敛，华容别后倩谁看。","风过绿酒和花饮，月晃银筝带泪弹。","此去凤城多近远，到时千万寄平安。"]},{"t":"过扬州怀萧太守惟一二首 其一","f":"七言律诗","c":["不到扬州四五年，凌风台观尚依然。","天晴锦树开千叶，雨过琼花耀八仙。","杜牧愁来春寂寂，何郎老去月娟娟。","风流太守今尘土，谁借缠腰十万钱。"]},{"t":"过扬州怀萧太守惟一二首 其二","f":"七言律诗","c":["二十四桥春水波，东风杨柳客船过。","关心往事成陈迹，照眼花枝奈老何。","狂客此时全错落，紫骝无状玉盘陀。","淡云芳草繁华地，不道游人感慨多。"]},{"t":"寄扬州通府解真白","f":"七言律诗","c":["我与黄昌是故人，也知通守最情真。","诗如水部翻成癖，官到黄州只自贫。","妒雪琼花台观旧，行春露冕岁华新。","悬知别思如春柳，长遣飞花到泗滨。"]},{"t":"金山寺","f":"七言律诗","c":["玄洲贝阙烂相辉，夹岸人家对敞扉。","四壁波涛长触石，孤山花木自成围。","横江鹤向扬州去，泛棹僧从建业归。","迁客凭阑重回首，蓬莱云气晓熹微。"]},{"t":"送牛应祥都阃","f":"七言律诗","c":["将军淮北分符地，正在隋家古汴河。","别馆芙蓉飘绣帽，御堤杨柳映雕戈。","强兵戍久通胡语，降虏年深解汉歌。","此去看花朝上国，春风天上听鸣珂。"]},{"t":"送夏仲寅之桐城","f":"七言律诗","c":["山到淮西迤逦平，舒州遥对皖公城。","怜君岁晚之官去，似我年时捧檄行。","书卷更因为县废，诗篇浑要在朝清。","寿阳千载遗祠庙，为捋江萍一荐馨。"]},{"t":"复虹县颜徵士景明","f":"七言律诗","c":["三淮北岸凉威早，六月秋风动虹亭。","公馆簿书长衮衮，汴堤杨柳自青青。","愁销楚客文鸳绮，梦返秦仙彩凤翎。","今雨襟期又云旷，暮云遥隔少微星。"]},{"t":"高邮","f":"七言律诗","c":["山日未出烟渺茫，高邮放船催下江。","摇橹唱歌白鹞子，过湖打鼓黄头郎。","鸟拖云叶低贴水，鱼噀浪花高接窗。","微官所得几何计，吟鬓四十今苍苍。"]},{"t":"秋风二首 其一","f":"七言律诗","c":["秋风淅淅吹屏山，汴何之水声潺潺。","归云一似宦情薄，飞雁不将乡信还。","千峰澹对寂寞景，孤客况栖羁旅间。","且可狂歌对樽酒，未须惨戚怀江关。"]},{"t":"秋风二首 其二","f":"七言律诗","c":["秋风淅淅吹江亭，汴河之柳犹青青。","黄姑东渡会七夕，白帝西来朝百灵。","初开琪树已云落，远别客愁今未醒。","欲写乡书寄南雁，故园万里天冥冥。"]},{"t":"虹县九日登五女冢五首 其一","f":"七言律诗","c":["又见殊方风物新，宦情羁思两纷纷。","楚山南下猿啼树，淮水东来雁拍云。","黄菊最怜贫靖节，西风还识旧参军。","远游所得都能几，三载柴扉怨鹤群。"]},{"t":"虹县九日登五女冢五首 其二","f":"七言律诗","c":["每爱华颠杜曲翁，登台此日对西风。","吟边菊蕊盈头白，醉里茱萸泼眼红。","故国音书凭去雁，殊方节物叹飘蓬。","风流拟欲追千古，寥落谁怜赋未工。"]},{"t":"虹县九日登五女冢五首 其三","f":"七言律诗","c":["肺气经秋久未平，佳辰酌酒看君倾。","雨催黄菊非无意，风落乌纱最有情。","仙客此时缑岭上，彩鸾何处玉箫声。","逶迟未就丹砂术，俯仰微官愧此生。"]},{"t":"虹县九日登五女冢五首 其四","f":"七言律诗","c":["老去佳辰得几逢，登临此会叹匆匆。","云来汴水波光白，日落屏山树杪红。","抱病独怜贫子美，休官惟羡老陶翁。","遥知弟妹家山里，几向天涯倚断鸿。"]},{"t":"虹县九日登五女冢五首 其五","f":"七言律诗","c":["玉女峰头烟树荒，登临聊得散徜徉。","忽惊重九今朝是，却忆三千客路长。","冷露馀花偏有色，朔云断雁不成行。","宁教醉里逢佳节，且免醒来望故乡。"]},{"t":"淮上思家","f":"七言律诗","c":["正月二月花草芳，水鹅拍拍茭菰塘。","卢橘荔枝赤璀璨，鸡头菱角青相将。","春光偏向越山好，客路苦阻淮天长。","飞鸿不解带愁思，空寄音书还故乡。"]},{"t":"淮南赠友","f":"七言律诗","c":["淮水西风吹白蘋，丹枫黄叶总愁人。","糕糍已入荆州俗，舴艋何时越水滨。","幸有故人同绮席，可无佳句慰芳辰。","清吟来拟追韦曲，一笑临风岸葛巾。"]},{"t":"淮上忆京","f":"七言律诗","c":["去岁兹辰客帝畿，蒋陵西曲雁飞飞。","秋风丛菊开芳径，落日浮云满翠微。","老去吟边风物改，别来天上故人稀。","登临复对青樽酒，醉倚淮山忆禁闱。"]},{"t":"清河口","f":"七言律诗","c":["清河黄河相间流，四月五月如九秋。","墨云压地箕斗黑，浊浪吐雪鱼龙愁。","江河万里杳何极，行役半生犹未休。","故园清兴自不浅，此日松竹风飕飕。"]},{"t":"圮上怀古","f":"七言律诗","c":["草没荒台烟树疏，维舟凝眺久踟躇。","凌波见说求仙履，博浪曾闻误副车。","勋业赤龙三尺剑，风云黄石一编书。","独怜衣赭人如玉，鸿鹄歌残怨有馀。"]},{"t":"过三洪","f":"七言律诗","c":["官舟已落三洪口，犹在飞流澒涌间。","放棹忽闻过乱石，开窗始觉慰愁颜。","云连雪浪瞿塘峡，树隐青泥古剑关。","谩有微吟追太白，此身疑谪夜郎还。"]},{"t":"过吕梁二首 其一","f":"七言律诗","c":["二月三月寒尚饶，上洪下洪春雪消。","奔霆出地星火裂，吼浪触石鼋鼍骄。","晨昏雾底苍水佩，明灭云中丹凤箫。","灵风为我送归棹，故国越海天迢迢。"]},{"t":"过吕梁二首 其二","f":"七言律诗","c":["彭城三月风未和，吕梁雪消春水多。","浊浪蟠空作飞雨，崩涛薄岸成盘涡。","鲛人珠佩影明灭，龙女金支光荡摩。","故山云物几时见，迁客此地长经过。"]},{"t":"徐州洪二首 其一","f":"七言律诗","c":["吕梁积石天峥嵘，徐州上洪波稍平。","蛟龙怒卷四时雨，砥柱乱落三秋星。","辛夷杜若散洲渚，贝阙珠宫开窈冥。","舟人倚棹笑相语，九里山色连彭城。"]},{"t":"徐州洪二首 其二","f":"七言律诗","c":["龙门铁石倚天开，仿佛瞿塘滟滪堆。","万里江风来灏气，九秋晴雪迸惊雷。","层阴水府和云见，浊浪漩涡划岸回。","小舣扁舟待明发，霸王台下久徘徊。"]}]};